        "pfad_leer_beschreibung": ["de": "Dein Pfad beginnt beim ersten Start der App.", "en": "Your path starts when you first open the app.", "es": "Tu camino comienza cuando abres la app por primera vez.", "fr": "Ton chemin commence quand tu ouvres l'application pour la première fois.", "it": "Il tuo percorso inizia al primo avvio dell'app.", "pt": "O teu caminho começa quando abres a aplicação pela primeira vez.", "ja": "初めてアプリを開いたときにパスが始まります。", "ko": "앱을 처음 열면 경로가 시작됩니다.", "pl": "Twoja ścieżka zaczyna się, gdy po raz pierwszy otworzysz aplikację.", "nl": "Uw pad begint wanneer u de app voor het eerst opent.", "tr": "Yolunuz uygulamayı ilk açtığınızda başlar."],
        "pfad_fit_day_1_title": ["de": "Der erste Schritt", "en": "The First Step", "es": "El primer paso", "fr": "Le premier pas", "it": "Il primo passo", "pt": "O primeiro passo", "ja": "最初のステップ", "ko": "첫 번째 단계", "pl": "Pierwszy krok", "nl": "De eerste stap", "tr": "İlk Adım"],
        "pfad_fit_day_1_desc": ["de": "Mach heute 10 Liegestütze. Qualität vor Quantität.", "en": "Do 10 pushups today. Quality over quantity.", "es": "Haz 10 flexiones hoy. Calidad sobre cantidad.", "fr": "Fais 10 pompes aujourd'hui. Qualité avant quantité.", "it": "Fai 10 flessioni oggi. Qualità prima della quantità.", "pt": "Faz 10 flexões hoje. Qualidade acima de quantidade.", "ja": "今日は腕立て伏せを10回やってみよう。量より質。", "ko": "오늘 팔굽혀펴기 10개를 해보세요. 양보다 질.", "pl": "Zrób dzisiaj 10 pompek. Jakość ponad ilość.", "nl": "Doe vandaag 10 push-ups. Kwaliteit boven kwantiteit.", "tr": "Bugün 10 şınav çekin. Miktarın üzerinde kalite."],
        "pfad_fit_day_7_title": ["de": "Eine Woche!", "en": "One Week!", "es": "¡Una semana!", "fr": "Une semaine !", "it": "Una settimana!", "pt": "Uma semana!", "ja": "一週間！", "ko": "일주일!", "pl": "Jeden tydzień!", "nl": "Eén week!", "tr": "Bir Hafta!"],
        "pfad_fit_day_7_desc": ["de": "20 Liegestütze heute. Du hast bewiesen dass du es kannst.", "en": "20 pushups today. You've proven that you can do it.", "es": "20 flexiones hoy. Has demostrado que puedes hacerlo.", "fr": "20 pompes aujourd'hui. Tu as prouvé que tu en es capable.", "it": "20 flessioni oggi. Hai dimostrato di potercela fare.", "pt": "20 flexões hoje. Provaste que consegues fazê-lo.", "ja": "今日は腕立て伏せ20回。あなたはそれができることを証明しました。", "ko": "오늘은 팔굽혀펴기 20개. 당신은 그것을 할 수 있다는 것을 증명했습니다.", "pl": "Dzisiaj 20 pompek. Udowodniłeś, że możesz to zrobić.", "nl": "Vandaag 20 push-ups. Je hebt bewezen dat je het kunt.", "tr": "Bugün 20 şınav. Bunu yapabileceğini kanıtladın."],
        "pfad_fit_day_14_title": ["de": "Zwei Wochen!", "en": "Two Weeks!", "es": "¡Dos semanas!", "fr": "Deux semaines !", "it": "Due settimane!", "pt": "Duas semanas!", "ja": "2週間！", "ko": "2주!", "pl": "Dwa tygodnie!", "nl": "Twee weken!", "tr": "İki Hafta!"],
        "pfad_fit_day_14_desc": ["de": "25 Liegestütze + 2 Minuten Plank. Du bist auf dem Weg zur Meisterschaft.", "en": "25 pushups + 2 minutes plank. You're on your way to mastery.", "es": "25 flexiones + 2 minutos de plancha. Estás de camino a la maestría.", "fr": "25 pompes + 2 minutes de gainage. Tu es sur la voie de la maîtrise.", "it": "25 flessioni + 2 minuti di plank. Sei sulla strada per la maestria.", "pt": "25 flexões + 2 minutos de prancha. Estás no caminho para a mestria.", "ja": "腕立て伏せ25回+プランク2分。あなたはマスターへの道を進んでいます。", "ko": "팔굽혀펴기 25개 + 플랭크 2분. 당신은 숙달을 향해 가고 있습니다.", "pl": "25 pompek + 2 minuty deski. Jesteś na dobrej drodze do mistrzostwa.", "nl": "25 push-ups + 2 minuten plank. Je bent op weg naar meesterschap.", "tr": "25 şınav + 2 dakika plank. Ustalığa giden yoldasın."],
        "pfad_fit_day_30_title": ["de": "Ein Monat!", "en": "One Month!", "es": "¡Un mes!", "fr": "Un mois !", "it": "Un mese!", "pt": "Um mês!", "ja": "1ヶ月！", "ko": "한 달!", "pl": "Jeden miesiąc!", "nl": "Eén maand!", "tr": "Bir Ay!"],
        "pfad_fit_day_30_desc": ["de": "30 Tage Fitness. Heute: maximale Leistung — so viele Liegestütze wie möglich.", "en": "30 days of fitness. Today: maximum performance — as many pushups as possible.", "es": "30 días de fitness. Hoy: rendimiento máximo - tantas flexiones como sea posible.", "fr": "30 jours de fitness. Aujourd'hui : performance maximale — autant de pompes que possible.", "it": "30 giorni di fitness. Oggi: prestazioni massime.", "pt": "30 dias de fitness. Hoje: desempenho máximo.", "ja": "30日間のフィットネス。今日: 最大限のパフォーマンス — できるだけ多くの腕立て伏せ。", "ko": "30일 피트니스. 오늘: 최대 성능 — 가능한 한 많은 푸시업.", "pl": "30 dni fitnessu. Dzisiaj: maksimum wydajności – jak najwięcej pompek.", "nl": "30 dagen fitness. Vandaag: maximale prestaties – zoveel mogelijk push-ups.", "tr": "30 günlük fitness. Bugün: maksimum performans - mümkün olduğu kadar çok şınav."],
        "pfad_produktiv_day_1_title": ["de": "Fokus-Zeit", "en": "Focus Time", "es": "Tiempo de enfoque", "fr": "Temps de concentration", "it": "Tempo di concentrazione", "pt": "Tempo de foco", "ja": "集中時間", "ko": "집중 시간", "pl": "Czas skupienia", "nl": "Focustijd", "tr": "Odaklanma Süresi"],
        "pfad_produktiv_day_1_desc": ["de": "Arbeite heute 25 Minuten ohne Ablenkung.", "en": "Work for 25 minutes without distraction today.", "es": "Trabaja hoy 25 minutos sin distracciones.", "fr": "Travaille 25 minutes sans distraction aujourd'hui.", "it": "Lavora per 25 minuti senza distrazioni oggi.", "pt": "Trabalha 25 minutos sem distração hoje.", "ja": "今日は気を散らさずに 25 分間仕事をしましょう。", "ko": "오늘은 방해받지 않고 25분 동안 일하세요.", "pl": "Pracuj dzisiaj przez 25 minut bez rozpraszania uwagi.", "nl": "Werk vandaag 25 minuten zonder afleiding.", "tr": "Bugün dikkatiniz dağılmadan 25 dakika çalışın."],
        "pfad_produktiv_day_7_title": ["de": "Wochenplanung", "en": "Weekly Planning", "es": "Planificación semanal", "fr": "Planification hebdomadaire", "it": "Pianificazione settimanale", "pt": "Planeamento semanal", "ja": "週間計画", "ko": "주간 계획", "pl": "Planowanie tygodniowe", "nl": "Wekelijkse planning", "tr": "Haftalık Planlama"],
        "pfad_produktiv_day_7_desc": ["de": "Plane heute deine kommenden 7 Tage im Voraus.", "en": "Plan your next 7 days in advance today.", "es": "Planifica hoy tus próximos 7 días con antelación.", "fr": "Planifie aujourd'hui tes 7 prochains jours à l'avance.", "it": "Pianifica oggi i tuoi prossimi 7 giorni in anticipo.", "pt": "Planeia hoje os teus próximos 7 dias com antecedência.", "ja": "今日から 7 日前に次の計画を立てましょう。", "ko": "오늘부터 다음 7일을 미리 계획해 보세요.", "pl": "Zaplanuj swoje kolejne 7 dni wcześniej już dziś.", "nl": "Plan vandaag nog uw volgende 7 dagen van tevoren.", "tr": "Gelecek 7 gününüzü bugün önceden planlayın."],
        "pfad_mental_day_1_title": ["de": "Pause", "en": "Break", "es": "Descanso", "fr": "Pause", "it": "Pausa", "pt": "Pausa", "ja": "壊す", "ko": "부서지다", "pl": "Przerwa", "nl": "Pauze", "tr": "Kırmak"],
        "pfad_mental_day_1_desc": ["de": "Nimm dir heute 2 Minuten nur zum Atmen.", "en": "Take 2 minutes today just to breathe.", "es": "Tómate 2 minutos hoy solo para respirar.", "fr": "Prends 2 minutes aujourd'hui juste pour respirer.", "it": "Prenditi 2 minuti oggi solo per respirare.", "pt": "Dedica 2 minutos hoje só para respirar.", "ja": "今日は 2 分間だけ息を吸ってください。", "ko": "오늘은 2분만 호흡해 보세요.", "pl": "Poświęć dzisiaj 2 minuty na oddychanie.", "nl": "Neem vandaag 2 minuten de tijd om adem te halen.", "tr": "Bugün sadece nefes almaya 2 dakika ayırın."],
        "pfad_lernen_day_1_title": ["de": "Wissensdurst", "en": "Thirst for Knowledge", "es": "Sed de conocimiento", "fr": "Soif de connaissance", "it": "Sete di conoscenza", "pt": "Sede de conhecimento", "ja": "知識への渇望", "ko": "지식에 대한 갈증", "pl": "Pragnienie wiedzy", "nl": "Dorst naar kennis", "tr": "Bilgiye Susuzluk"],
        "pfad_lernen_day_1_desc": ["de": "Lies heute genau 5 Seiten in einem Buch.", "en": "Read exactly 5 pages in a book today.", "es": "Lee hoy exactamente 5 páginas de un libro.", "fr": "Lis exactement 5 pages d'un livre aujourd'hui.", "it": "Leggi esattamente 5 pagine di un libro oggi.", "pt": "Lê exatamente 5 páginas num livre hoje.", "ja": "今日は本をちょうど 5 ページ読みましょう。", "ko": "오늘 책 한 권을 정확히 5페이지 읽어 보세요.", "pl": "Przeczytaj dzisiaj dokładnie 5 stron książki.", "nl": "Lees vandaag precies 5 pagina's in een boek.", "tr": "Bugün bir kitaptan tam olarak 5 sayfa okuyun."],
        "pfad_gesund_day_1_title": ["de": "Hydrierung", "en": "Hydration", "es": "Hidratación", "fr": "Hydratation", "it": "Idratazione", "pt": "Hidratação", "ja": "水分補給", "ko": "수분 공급", "pl": "Uwodnienie", "nl": "Hydratatie", "tr": "Hidrasyon"],
        "pfad_gesund_day_1_desc": ["de": "Trinke heute 2 Liter Wasser.", "en": "Drink 2 liters of water today.", "es": "Bebe hoy 2 litros de agua.", "fr": "Bois 2 litres d'eau aujourd'hui.", "it": "Bevi 2 litri d'acqua oggi.", "pt": "Bebe 2 litros de água hoje.", "ja": "今日は水を2リットル飲みましょう。", "ko": "오늘은 물 2리터를 마셔보세요.", "pl": "Wypij dzisiaj 2 litry wody.", "nl": "Drink vandaag 2 liter water.", "tr": "Bugün 2 litre su iç."],
        "pfad_fehlt_day_1_title": ["de": "Eigener Start", "en": "Your Own Start", "es": "Tu propio inicio", "fr": "Ton propre début", "it": "Il tuo inizio", "pt": "O teu próprio início", "ja": "あなた自身のスタート", "ko": "나만의 시작", "pl": "Twój własny początek", "nl": "Je eigen begin", "tr": "Kendi Başlangıçınız"],
        "pfad_fehlt_day_1_desc": ["de": "Erster Tag deines persönlichen Ziels.", "en": "First day of your personal goal.", "es": "Primer día de tu objetivo personal.", "fr": "Premier jour de ton objectif personnel.", "it": "Primo giorno del tuo obiettivo personale.", "pt": "Primeiro dia do teu objetivo pessoal.", "ja": "個人的な目標の初日。", "ko": "개인 목표의 첫날.", "pl": "Pierwszy dzień Twojego osobistego celu.", "nl": "Eerste dag van je persoonlijke doel.", "tr": "Kişisel hedefinizin ilk günü."],
        "pfad_fit_phase_einstieg_desc": ["de": "Gewöhne deinen Körper an tägliche Bewegung. Kleine Schritte führen weit.", "en": "Get your body used to daily movement. Small steps go a long way.", "es": "Acostumbra tu cuerpo al movimiento diario. Los pequeños pasos llevan lejos.", "fr": "Habitue ton corps à une activité quotidienne. Les petits pas mènent loin.", "it": "Abitua il tuo corpo al movimento quotidiano. Piccoli passi portano lontano.", "pt": "Habitua o teu corpo ao movimento diário. Pequenos passos levam longe.", "ja": "日々の動きに体を慣れさせましょう。小さな一歩が大きく前進します。", "ko": "일상적인 움직임에 몸을 익숙해지세요. 작은 발걸음이 먼 길을 갑니다.", "pl": "Przyzwyczajaj swoje ciało do codziennego ruchu. Małymi krokami można osiągnąć długą drogę.", "nl": "Laat uw lichaam wennen aan dagelijkse beweging. Met kleine stapjes kom je een heel eind.", "tr": "Vücudunuzu günlük hareketlere alıştırın. Küçük adımlar uzun bir yol kat eder."],
        "pfad_produktiv_phase_einstieg_desc": ["de": "Finde deinen Rhythmus. Eine fokussierte Einheit heute.", "en": "Find your rhythm. One focused session today.", "es": "Encuentra tu ritmo. Una sesión enfocada hoy.", "fr": "Trouve ton rythme. Une session concentrée aujourd'hui.", "it": "Trova il tuo ritmo. Una sessione focalizzata oggi.", "pt": "Encontra o teu ritmo. Uma sessão focada hoje.", "ja": "自分のリズムを見つけてください。今日は集中的なセッションが 1 つあります。", "ko": "당신의 리듬을 찾아보세요. 오늘은 집중 세션입니다.", "pl": "Znajdź swój rytm. Dzisiaj jedna skupiona sesja.", "nl": "Vind jouw ritme. Eén gerichte sessie vandaag.", "tr": "Ritiminizi bulun. Bugün odaklanmış bir oturum."],
        "pfad_mental_phase_einstieg_desc": ["de": "Kleine Auszeiten für den Geist. Lerne bewusstes Atmen.", "en": "Short breaks for the mind. Learn conscious breathing.", "es": "Pequeños descansos para la mente. Aprende a respirar conscientemente.", "fr": "Courtes pauses pour l'esprit. Apprends la respiration consciente.", "it": "Brevi pause per la mente. Impara la respirazione consapevole.", "pt": "Curta pausa para a mente. Aprende a respiração consciente.", "ja": "心の短い休憩。意識的な呼吸法を学びましょう。", "ko": "마음을 위한 짧은 휴식. 의식적인 호흡을 배우십시오.", "pl": "Krótkie przerwy dla umysłu. Naucz się świadomego oddychania.", "nl": "Korte pauzes voor de geest. Leer bewust ademen.", "tr": "Zihin için kısa molalar. Bilinçli nefes almayı öğrenin."],
        "pfad_lernen_phase_einstieg_desc": ["de": "Baue deine tägliche Lesegewohnheit auf. Ein paar Seiten am Tag helfen.", "en": "Build your daily reading habit. A few pages a day help.", "es": "Crea tu hábito de lectura diario. Unas pocas páginas al día ayudan.", "fr": "Crée une habitude de lecture quotidienne. Quelques pages par jour aident.", "it": "Sviluppa la tua abitudine di lettura quotidiana. Poche pagine al giorno aiutano.", "pt": "Constrói o teu hábito diário de leitura. Algumas páginas por dia ajudam.", "ja": "毎日の読書習慣を築きましょう。 1日数ページでも効果があります。", "ko": "매일 독서 습관을 기르세요. 하루에 몇 페이지씩 도움이 됩니다.", "pl": "Zbuduj swój codzienny nawyk czytania. Kilka stron dziennie pomaga.", "nl": "Bouw uw dagelijkse leesgewoonte op. Een paar pagina's per dag helpen.", "tr": "Günlük okuma alışkanlığınızı geliştirin. Günde birkaç sayfa yardımcı olur."],
        "pfad_gesund_phase_einstieg_desc": ["de": "Achte auf deine tägliche Wasserzufuhr für mehr Lebensenergie.", "en": "Pay attention to your daily water intake for more vital energy.", "es": "Presta atención a tu ingesta diaria de agua para tener más energía vital.", "fr": "Fais attention à ton apport quotidien en eau pour plus d'énergie vitale.", "it": "Fai attenzione al tuo apporto giornaliero di acqua per più energia vitale.", "pt": "Presta atenção à tua ingestão diária de água para mais energia vital.", "ja": "より多くの生命エネルギーを得るために、毎日の水分摂取量に注意してください。", "ko": "더 활력 있는 에너지를 얻으려면 일일 물 섭취량에 주의를 기울이세요.", "pl": "Zwróć uwagę na dzienne spożycie wody, aby uzyskać więcej energii życiowej.", "nl": "Besteed aandacht aan uw dagelijkse waterinname voor meer vitale energie.", "tr": "Daha hayati enerji için günlük su alımınıza dikkat edin."],
        "pfad_fehlt_phase_einstieg_desc": ["de": "Der Beginn von etwas Großem. Dein persönliches Ziel wartet.", "en": "The beginning of something great. Your personal goal awaits.", "es": "El comienzo de algo grande. Tu objetivo personal te espera.", "fr": "Le début de quelque chose de grand. Ton objectif personnel t'attend.", "it": "L'inizio di qualcosa di grande. Il tuo obiettivo personale ti aspetta.", "pt": "O início de algo grande. O teu objetivo pessoal espera por ti.", "ja": "素晴らしいものの始まり。あなたの個人的な目標が待っています。", "ko": "위대한 일의 시작. 당신의 개인적인 목표가 기다리고 있습니다.", "pl": "Początek czegoś wielkiego. Twój osobisty cel czeka.", "nl": "Het begin van iets groots. Jouw persoonlijke doel wacht op je.", "tr": "Harika bir şeyin başlangıcı. Kişisel hedefiniz sizi bekliyor."],
        "pfad_fit_day_45_title": ["de": "Halbzeit!", "en": "Halfway!", "es": "¡Mitad del camino!", "fr": "À mi-chemin !", "it": "Metà strada!", "pt": "Meio do caminho!", "ja": "中途半端！", "ko": "반쯤!", "pl": "Wpół!", "nl": "Halverwege!", "tr": "Yarı yolda!"],
        "pfad_fit_day_45_desc": ["de": "45 Tage Fitness. Dein Körper hat sich bereits verändert. Bleib stark!", "en": "45 days of fitness. Your body has already changed. Stay strong!", "es": "45 días de fitness. Tu cuerpo ya ha cambiado. ¡Mantente fuerte!", "fr": "45 jours de fitness. Ton corps a déjà changé. Reste fort !", "it": "45 giorni di fitness. Il tuo corpo è già cambiato. Rimani forte!", "pt": "45 dias de fitness. O teu corpo já mudou. Mantém-te forte!", "ja": "45日間のフィットネス。あなたの体はすでに変化しています。強くありなさい！", "ko": "45일간의 피트니스. 당신의 몸은 이미 변했습니다. 힘내세요!", "pl": "45 dni fitness. Twoje ciało już się zmieniło. Bądź silny!", "nl": "45 dagen fitness. Je lichaam is al veranderd. Blijf sterk!", "tr": "45 günlük fitness. Vücudunuz zaten değişti. Güçlü kal!"],
        "pfad_fit_day_60_title": ["de": "Zwei Monate!", "en": "Two Months!", "es": "¡Dos meses!", "fr": "Deux mois !", "it": "Due mesi!", "pt": "Dois meses!", "ja": "2ヶ月！", "ko": "두 달!", "pl": "Dwa miesiące!", "nl": "Twee maanden!", "tr": "İki Ay!"],
        "pfad_fit_day_60_desc": ["de": "60 Tage. Fitness ist nun ein fester Teil deines Lebens.", "en": "60 days. Fitness is now a fixed part of your life.", "es": "60 días. El fitness es ahora una parte fija de tu vida.", "fr": "60 jours. Le fitness fait maintenant partie intégrante de ta vie.", "it": "60 giorni. Il fitness è ormai una parte fissa della tua vita.", "pt": "60 dias. O fitness é agora uma parte fixa da tua vida.", "ja": "60日。フィットネスは今やあなたの生活の一部となっています。", "ko": "60일 피트니스는 이제 삶의 고정된 부분입니다.", "pl": "60 dni. Fitness jest teraz stałą częścią Twojego życia.", "nl": "60 dagen. Fitness is nu een vast onderdeel van uw leven.", "tr": "60 gün. Fitness artık hayatınızın sabit bir parçası."],
        "pfad_fit_day_90_title": ["de": "Meisterschaft erreicht!", "en": "Mastery reached!", "es": "¡Maestría alcanzada!", "fr": "Maîtrise atteinte !", "it": "Maestria raggiunta!", "pt": "Mestria alcançada!", "ja": "マスタリー到達！", "ko": "마스터리 달성!", "pl": "Mistrzostwo osiągnięte!", "nl": "Meesterschap bereikt!", "tr": "Ustalığa ulaşıldı!"],
        "pfad_fit_day_90_desc": ["de": "90 Tage. Du hast das Unmögliche möglich gemacht. Du bist ein Meister.", "en": "90 days. You have made the impossible possible. You are a master.", "es": "90 días. Has hecho posible lo imposible. Eres un maestro.", "fr": "90 jours. Tu as rendu l'impossible possible. Tu es un maître.", "it": "90 giorni. Hai reso possibile l'impossibile. Sei un maestro.", "pt": "90 dias. Fizeste o impossível possível. És um mestre.", "ja": "90日。あなたは不可能を可能にしました。あなたはマスターです。", "ko": "90일. 불가능을 가능하게 만드셨습니다. 당신은 마스터입니다.", "pl": "90 dni. Sprawiłeś, że niemożliwe stało się możliwe. Jesteś mistrzem.", "nl": "90 dagen. Je hebt het onmogelijke mogelijk gemaakt. Je bent een meester.", "tr": "90 gün. İmkansızı mümkün kıldınız. Sen bir ustasın."],
        "pfad_fit_phase_vertiefung_desc": ["de": "Vertiefe dein Training. Dein Körper wird noch stärker.", "en": "Deepen your training. Your body is getting even stronger.", "es": "Profundiza tu entrenamiento. Tu cuerpo se está volviendo aún más fuerte.", "fr": "Approfondis ton entraînement. Ton corps devient encore plus fort.", "it": "Approfondisci il tuo allenamento. Il tuo corpo sta diventando ancora più forte.", "pt": "Aprofunda o teu treino. O teu corpo está a ficar ainda mais forte.", "ja": "トレーニングを深めてください。あなたの体はさらに強くなっていきます。", "ko": "훈련을 심화하세요. 당신의 몸은 더욱 강해지고 있습니다.", "pl": "Pogłębiaj swój trening. Twoje ciało staje się jeszcze silniejsze.", "nl": "Verdiep je training. Je lichaam wordt nog sterker.", "tr": "Eğitiminizi derinleştirin. Vücudunuz daha da güçleniyor."],
        "pfad_produktiv_phase_vertiefung_desc": ["de": "Meistere deine Zeit. Fokus wird zur Gewohnheit.", "en": "Master your time. Focus becomes a habit.", "es": "Domina tu tiempo. El enfoque se convierte en un hábito.", "fr": "Maîtrise ton temps. La concentration devient une habitude.", "it": "Padroneggia il tuo tempo. Il focus diventa un'abitudine.", "pt": "Domina o teu tempo. O foco torna-se um hábito.", "ja": "時間をマスターしましょう。集中力が習慣になります。", "ko": "시간을 마스터하세요. 집중은 습관이 됩니다.", "pl": "Opanuj swój czas. Koncentracja staje się nawykiem.", "nl": "Beheers uw tijd. Focus wordt een gewoonte.", "tr": "Zamanınıza hakim olun. Odaklanmak bir alışkanlık haline gelir."],
        "pfad_mental_phase_vertiefung_desc": ["de": "Innere Stärke kultivieren. Frieden findest du in dir.", "en": "Cultivate inner strength. You find peace within yourself.", "es": "Cultiva la fuerza interior. Encuentras la paz dentro de ti.", "fr": "Cultive ta force intérieure. Tu trouves la paix en toi-même.", "it": "Coltiva la forza interiore. Trovi la pace dentro di te.", "pt": "Cultiva a força interior. Encontras a paz dentro de ti.", "ja": "内なる強さを養いましょう。あなたは自分自身の中に平和を見出します。", "ko": "내면의 힘을 키우세요. 당신은 자신 안에서 평화를 찾습니다.", "pl": "Pielęgnuj wewnętrzną siłę. Odnajdujesz spokój w sobie.", "nl": "Cultiveer innerlijke kracht. Je vindt rust in jezelf.", "tr": "İçsel gücü geliştirin. Huzuru kendi içinde bulursun."],
        "pfad_lernen_phase_vertiefung_desc": ["de": "Wissen vernetzen. Du lernst nun komplexe Zusammenhänge.", "en": "Network knowledge. You are now learning complex connections.", "es": "Conecta conocimientos. Ahora estás aprendiendo conexiones complejas.", "fr": "Réseautage des connaissances. Tu apprends maintenant des liens complexes.", "it": "Metti in rete le conoscenze. Ora stai imparando connessioni complesse.", "pt": "Conecta conhecimentos. Estás agora a aprender ligações complexas.", "ja": "ネットワークの知識。あなたは今、複雑な接続を学習しています。", "ko": "네트워크 지식. 당신은 이제 복잡한 연결을 배우고 있습니다.", "pl": "Znajomość sieci. Teraz uczysz się złożonych połączeń.", "nl": "Netwerk kennis. Je leert nu complexe verbindingen.", "tr": "Ağ bilgisi. Artık karmaşık bağlantıları öğreniyorsunuz."],
        "pfad_gesund_phase_vertiefung_desc": ["de": "Gesundheit maximieren. Dein Körper dankt dir jeden Tag.", "en": "Maximize health. Your body thanks you every day.", "es": "Maximiza la salud. Tu cuerpo te lo agradece cada día.", "fr": "Maximise ta santé. Ton corps te remercie chaque jour.", "it": "Massimizza la salute. Il tuo corpo ti ringrazia ogni giorno.", "pt": "Maximiza a saúde. O teu corpo agradece-te todos os dias.", "ja": "健康を最大限に高めます。あなたの体は毎日あなたに感謝しています。", "ko": "건강을 극대화하세요. 당신의 몸은 매일 당신에게 감사합니다.", "pl": "Maksymalizuj zdrowie. Twoje ciało dziękuje Ci każdego dnia.", "nl": "Maximaliseer de gezondheid. Je lichaam bedankt je elke dag.", "tr": "Sağlığı en üst düzeye çıkarın. Vücudunuz size her gün teşekkür ediyor."],
        "pfad_fehlt_phase_vertiefung_desc": ["de": "Bleib dran an deinem Ziel. Du bist fast da.", "en": "Stay focused on your goal. You are almost there.", "es": "Mantente enfocado en tu meta. Casi estás ahí.", "fr": "Reste concentré sur ton objectif. Tu y es presque.", "it": "Rimani concentrato sul tuo obiettivo. Ci sei quasi.", "pt": "Mantém-te focado no teu objetivo. Estás quase lá.", "ja": "目標に集中してください。もうすぐそこです。", "ko": "목표에 계속 집중하세요. 거의 다 왔습니다.", "pl": "Skoncentruj się na swoim celu. Już prawie jesteś.", "nl": "Blijf gefocust op je doel. Je bent er bijna.", "tr": "Hedefinize odaklanın. Neredeyse oradasın."],
        "pfad_fit_phase_meisterschaft_desc": ["de": "Du bist ein Fitness-Profi. Halte dieses Level.", "en": "You are a fitness pro. Maintain this level.", "es": "Eres un pro del fitness. Mantén este nivel.", "fr": "Tu es un pro du fitness. Maintiens ce niveau.", "it": "Sei un professionista del fitness. Mantieni questo livello.", "pt": "És um pro de fitness. Mantém este nível.", "ja": "あなたはフィットネスのプロです。このレベルを維持してください。", "ko": "당신은 피트니스 전문가입니다. 이 수준을 유지하세요.", "pl": "Jesteś profesjonalistą w dziedzinie fitnessu. Utrzymuj ten poziom.", "nl": "Je bent een fitnessprofessional. Houd dit niveau aan.", "tr": "Sen bir fitness uzmanısın. Bu seviyeyi koruyun."],
        "pfad_produktiv_phase_meisterschaft_desc": ["de": "Maximale Effizienz. Du beherrscht deinen Tag perfekt.", "en": "Maximum efficiency. You master your day perfectly.", "es": "Máxima eficiencia. Dominas tu día perfectamente.", "fr": "Efficacité maximale. Tu maîtrises parfaitement ta journée.", "it": "Massima efficienza. Padroneggi perfettamente la tua giornata.", "pt": "Eficiência máxima. Dominas o teu dia perfeitamente.", "ja": "最大の効率。あなたは一日を完璧にマスターします。", "ko": "최대의 효율성. 당신은 하루를 완벽하게 마스터합니다.", "pl": "Maksymalna wydajność. Doskonale opanowałeś swój dzień.", "nl": "Maximale efficiëntie. Je beheerst je dag perfect.", "tr": "Maksimum verimlilik. Gününüzü mükemmel bir şekilde yönetiyorsunuz."],
        "pfad_mental_phase_meisterschaft_desc": ["de": "Tiefe Gelassenheit. Du bist eins mit dir selbst.", "en": "Deep serenity. You are at one with yourself.", "es": "Serenidad profunda. Eres uno contigo mismo.", "fr": "Sérénité profonde. Tu ne fais qu'un avec toi-même.", "it": "Profonda serenità. Sei in armonia con te stesso.", "pt": "Serenidade profunda. Estás em harmonia contigo mesmo.", "ja": "深い静けさ。あなたは自分自身と一つになっています。", "ko": "깊은 평온함. 당신은 자신과 하나입니다.", "pl": "Głęboki spokój. Jesteś jednością ze sobą.", "nl": "Diepe sereniteit. Je bent één met jezelf.", "tr": "Derin huzur. Sen kendinle birsin."],
        "pfad_lernen_phase_meisterschaft_desc": ["de": "Lebenslanges Lernen. Wissen ist deine Superkraft.", "en": "Lifelong learning. Knowledge is your superpower.", "es": "Aprendizaje de por vida. El conocimiento es tu superpoder.", "fr": "Apprentissage tout au long de la vie. Le savoir est ton superpouvoir.", "it": "Apprendimento permanente. La conoscenza è il tuo superpotere.", "pt": "Aprendizagem ao longo da vida. O conhecimento é o teu superpoder.", "ja": "生涯学習。知識はあなたのスーパーパワーです。", "ko": "평생 학습. 지식은 당신의 초능력입니다.", "pl": "Uczenie się przez całe życie. Wiedza jest Twoją supermocą.", "nl": "Levenslang leren. Kennis is je superkracht.", "tr": "Yaşam boyu öğrenme. Bilgi sizin süper gücünüzdür."],
        "pfad_gesund_phase_meisterschaft_desc": ["de": "Goldener Status. Dein Körper ist dein Tempel.", "en": "Golden status. Your body is your temple.", "es": "Estado dorado. Tu cuerpo es tu templo.", "fr": "Statut doré. Ton corps est ton temple.", "it": "Status d'oro. Il tuo corpo è il tuo tempio.", "pt": "Estado de ouro. O teu corpo é o teu templo.", "ja": "ゴールデンステータス。あなたの体はあなたの神殿です。", "ko": "황금 상태. 당신의 몸은 당신의 사원입니다.", "pl": "Złoty status. Twoje ciało jest Twoją świątynią.", "nl": "Gouden status. Je lichaam is je tempel.", "tr": "Altın durumu. Vücudunuz sizin tapınağınızdır."],
        "pfad_fehlt_phase_meisterschaft_desc": ["de": "Ziel erreicht! Du hast bewiesen was in dir steckt.", "en": "Goal reached! You have proven what you are made of.", "es": "¡Meta alcanzada! Has demostrado de qué estás hecho.", "fr": "Objectif atteint ! Tu as prouvé de quoi tu es capable.", "it": "Obiettivo raggiunto! Hai dimostrato di che pasta sei fatto.", "pt": "Objetivo alcançado! Provaste do que és capaz.", "ja": "目標達成！あなたは自分が何でできているかを証明しました。", "ko": "목표 달성! 당신은 당신이 무엇으로 만들어졌는지 증명했습니다.", "pl": "Cel osiągnięty! Udowodniłeś, na co cię stać.", "nl": "Doel bereikt! Je hebt bewezen waar je van gemaakt bent.", "tr": "Hedefe ulaşıldı! Neyden yaratıldığınızı kanıtladınız."],
        "pfad_fehlt_phase_aufbau_desc": ["de": "Du machst Fortschritte. Steigere deinen persönlichen Einsatz heute.", "en": "You are making progress. Increase your personal effort today.", "es": "Estás progresando. Aumenta tu esfuerzo personal hoy.", "fr": "Tu fais des progrès. Augmente ton effort personnel aujourd'hui.", "it": "Stai facendo progressi. Aumenta il tuo impegno personale oggi.", "pt": "Estás a progredir. Aumenta o teu esforço pessoal hoje.", "ja": "進歩していますね。今日は個人の努力を増やしてください。", "ko": "당신은 발전하고 있습니다. 오늘 개인적인 노력을 더 많이 하십시오.", "pl": "Robisz postępy. Zwiększ swój osobisty wysiłek już dziś.", "nl": "Je boekt vooruitgang. Verhoog vandaag nog uw persoonlijke inspanning.", "tr": "İlerleme kaydediyorsun. Bugün kişisel çabanızı artırın."],
