        "pfad_mental_day_7_title": ["de": "Eine Woche Achtsamkeit", "en": "One Week of Mindfulness", "es": "Una semana de atención plena", "fr": "Une semaine de pleine conscience", "it": "Una settimana di consapevolezza", "pt": "Uma semana de consciência", "ja": "1週間のマインドフルネス", "ko": "일주일의 마음챙김", "pl": "Tydzień uważności", "nl": "Eén week mindfulness", "tr": "Bir Hafta Farkındalık"],
        "pfad_mental_day_7_desc": ["de": "Du hast 7 Tage lang bewusst geatmet. Spürst du die Ruhe?", "en": "You have breathed consciously for 7 days. Do you feel the peace?", "es": "Has respirado conscientemente durante 7 días. ¿Sientes la paz?", "fr": "Tu as respiré consciemment pendant 7 jours. Sens-tu le calme ?", "it": "Hai respirato consapevolmente per 7 giorni. Senti la pace?", "pt": "Respiraste conscientemente durante 7 dias. Sentes a paz?", "ja": "あなたは 7 日間意識的に呼吸しました。平和を感じていますか？", "ko": "당신은 7일 동안 의식적으로 호흡했습니다. 평화를 느끼시나요?", "pl": "Oddychasz świadomie przez 7 dni. Czy czujesz spokój?", "nl": "Je hebt 7 dagen bewust ademgehaald. Voel jij de vrede?", "tr": "7 gün boyunca bilinçli nefes aldınız. Huzuru hissediyor musun?"],
        "pfad_lernen_day_7_title": ["de": "Wissens-Woche", "en": "Knowledge Week", "es": "Semana del conocimiento", "fr": "Semaine du savoir", "it": "Settimana della conoscenza", "pt": "Semana do conhecimento", "ja": "ナレッジウィーク", "ko": "지식 주간", "pl": "Tydzień Wiedzy", "nl": "Kennisweek", "tr": "Bilgi Haftası"],
        "pfad_lernen_day_7_desc": ["de": "Ganze 7 Tage Lesen. Dein Wissen wächst wie dein Garten.", "en": "A full 7 days of reading. Your knowledge grows like your garden.", "es": "7 días enteros de lectura. Tu conocimiento crece como tu jardín.", "fr": "7 jours entiers de lecture. Ton savoir grandit comme ton jardin.", "it": "Interi 7 giorni di lettura. La tua conoscenza cresce come il tuo giardino.", "pt": "7 dias inteiros de leitura. O teu conhecimento cresce como o teu jardim.", "ja": "まるまる7日間の読書。あなたの知識はあなたの庭のように成長します。", "ko": "7일간의 독서. 당신의 지식은 정원처럼 자랍니다.", "pl": "Pełne 7 dni czytania. Twoja wiedza rośnie jak Twój ogród.", "nl": "7 volle dagen leesplezier. Je kennis groeit als je tuin.", "tr": "Tam 7 gün okuma. Bilginiz bahçeniz gibi büyür."],
        "pfad_gesund_day_7_title": ["de": "Hydrierungs-Profi", "en": "Hydration Pro", "es": "Pro de la hidratación", "fr": "Pro de l'hydratation", "it": "Pro dell'idratazione", "pt": "Pro da hidratação", "ja": "ハイドレーションプロ", "ko": "하이드레이션 프로", "pl": "Nawilżenie Pro", "nl": "Hydratatie Pro", "tr": "Hidrasyon Pro"],
        "pfad_gesund_day_7_desc": ["de": "7 Tage lang genug Wasser. Dein Körper dankt es dir.", "en": "Enough water for 7 days. Your body thanks you.", "es": "Suficiente agua durante 7 días. Tu cuerpo te lo agradece.", "fr": "Assez d'eau pendant 7 jours. Ton corps te remercie.", "it": "Abbastanza acqua per 7 giorni. Il tuo corpo ti ringrazia.", "pt": "Água suficiente durante 7 dias. O teu corpo agradece.", "ja": "7日分の水が足りる。あなたの体はあなたに感謝します。", "ko": "7일 동안 사용할 수 있는 충분한 물입니다. 당신의 몸은 당신에게 감사합니다.", "pl": "Wystarczająca ilość wody na 7 dni. Twoje ciało Ci dziękuje.", "nl": "Genoeg water voor 7 dagen. Je lichaam bedankt je.", "tr": "7 gün yetecek kadar su. Vücudunuz size teşekkür ediyor."],
