        "item.herz_auffueller.usage": ["de": "Wird sofort aktiv und füllt 1 Leben auf (Max. 5).", "en": "Becomes active immediately and restores 1 life (Max. 5).", "es": "Se activa de inmediato y restaura 1 vida (Máx. 5).", "fr": "S'active immédiatement et restaure 1 vie (Max. 5).", "it": "Si attiva immediatamente e ripristina 1 vita (Max. 5).", "pt": "Ativa imediatamente e restaura 1 vida (Máx. 5).", "ja": "即時発動しライフを1回復（最大5）。", "ko": "즉시 활성화되며 생명력을 1회 회복합니다(최대 5회).", "pl": "Staje się natychmiast aktywny i przywraca 1 życie (maks. 5).", "nl": "Wordt onmiddellijk actief en herstelt 1 leven (max. 5).", "tr": "Hemen aktif hale gelir ve 1 can yeniler (Maks. 5)."],
        "item.gartenschutz.name": ["de": "Gartenschutz", "en": "Garden Protection", "es": "Protección del Jardín", "fr": "Protection du jardin", "it": "Garden Protection", "pt": "Proteção do jardim", "ja": "庭園の保護", "ko": "정원 보호", "pl": "Ochrona ogrodu", "nl": "Tuinbescherming", "tr": "Bahçe Koruması"],
        "item.gartenschutz.usage": ["de": "Sofort aktiv: Dekorationen und Belohnungen spawnen keine neuen Unkräuter.", "en": "Active immediately: decorations and rewards won't spawn new weeds.", "es": "Activo al instante: sin malas hierbas nuevas.", "fr": "Actif immédiatement : pas de nouvelles mauvaises herbes.", "it": "Attivo subito: niente nuove erbacce.", "pt": "Ativo já: sem novas ervas daninhas.", "ja": "すぐにアクティブになります: 装飾や報酬によって新しい雑草が発生することはありません。", "ko": "즉시 활성화: 장식과 보상으로 인해 새로운 잡초가 생성되지 않습니다.", "pl": "Aktywne natychmiast: dekoracje i nagrody nie powodują powstawania nowych chwastów.", "nl": "Direct actief: decoraties en beloningen zullen geen nieuw onkruid voortbrengen.", "tr": "Hemen aktif olun: Dekorasyonlar ve ödüller yeni yabani otların ortaya çıkmasına neden olmaz."],
        "item.unkraut_schild.name": ["de": "Unkraut-Schild", "en": "Weed Shield", "es": "Escudo anti-hierbas", "fr": "Bouclier anti-mauvaises herbes", "it": "Scudo anti-erbacce", "pt": "Escudo anti-ervas", "ja": "ウィードシールド", "ko": "위드 쉴드", "pl": "Tarcza chwastów", "nl": "Onkruid schild", "tr": "Ot Kalkanı"],
        "item.unkraut_schild.description": ["de": "Entfernt Unkraut mit dem Schild-Ritual und schützt 24 Stunden vor neuem Unkraut.", "en": "Removes weeds with the shield ritual and protects against new weeds for 24 hours.", "es": "Elimina malas hierbas con el ritual del escudo y protege 24 h contra nuevas.", "fr": "Retire les mauvaises herbes par le rituel du bouclier et protège 24 h contre les nouvelles.", "it": "Rimuove le erbacce con il rituale dello scudo e protegge per 24 ore.", "pt": "Remove ervas com o ritual do escudo e protege 24 h contra novas.", "ja": "シールドリチュアルで雑草を除去し、新たな雑草を24時間防ぎます。", "ko": "방패 의식으로 잡초를 제거하고 24시간 동안 새로운 잡초를 막아줍니다.", "pl": "Usuwa chwasty za pomocą rytuału tarczy i chroni przed nowymi chwastami przez 24 godziny.", "nl": "Verwijdert onkruid met het schildritueel en beschermt 24 uur lang tegen nieuw onkruid.", "tr": "Kalkan ritüeli ile yabani otları yok eder ve 24 saat boyunca yeni yabani otlara karşı koruma sağlar."],
        "item.unkraut_schild.usage": ["de": "Bei Unkraut: Schild auf 1, 2 und 3 ziehen. Danach 24 h kein neues Unkraut.", "en": "When weeds appear: drag the shield onto 1, 2, and 3. Then 24 h without new weeds.", "es": "Con malas hierbas: arrastra el escudo a 1, 2 y 3. Luego 24 h sin nuevas.", "fr": "Avec des mauvaises herbes : glisse le bouclier sur 1, 2 et 3. Puis 24 h sans nouvelles.", "it": "Con erbacce: trascina lo scudo su 1, 2 e 3. Poi 24 h senza nuove.", "pt": "Com ervas: arrasta o escudo para 1, 2 e 3. Depois 24 h sem novas.", "ja": "雑草が現れたら、シールドを 1、2、3 にドラッグします。その後、新しい雑草が発生しない状態で 24 時間放置します。", "ko": "잡초가 나타나면 방패를 1, 2, 3으로 드래그하세요. 그런 다음 24시간 동안 새로운 잡초가 나오지 않습니다.", "pl": "Kiedy pojawią się chwasty: przeciągnij tarczę na 1, 2 i 3. Następnie 24 godziny bez nowych chwastów.", "nl": "Als er onkruid verschijnt: sleep het schild naar 1, 2 en 3. Daarna 24 uur zonder nieuw onkruid.", "tr": "Yabani otlar göründüğünde: kalkanı 1, 2 ve 3'e sürükleyin. Ardından 24 saat boyunca yeni yabani otlar olmadan."],
        "weed.powerup.hint.unkraut_schild": ["de": "Schild-Ritual + 24 h kein neues Unkraut", "en": "Shield ritual + 24 h no new weeds", "es": "Ritual del escudo + 24 h sin nuevas", "fr": "Rituel du bouclier + 24 h sans nouvelles", "it": "Rituale scudo + 24 h senza nuove", "pt": "Ritual do escudo + 24 h sem novas", "ja": "シールドの儀式 + 24 時間新たな雑草を排除", "ko": "방패 의식 + 24시간 잡초 제거", "pl": "Rytuał tarczy + 24 h bez nowych chwastów", "nl": "Schildritueel + 24u geen nieuw onkruid", "tr": "Kalkan ritüeli + 24 saat yeni yabani ot yok"],
        "item.giesscan_pro.description": ["de": "Hält deinen Garten länger feucht.", "en": "Keeps your garden moist longer.", "es": "Mantiene tu jardín húmedo por más tiempo.", "fr": "Garde ton jardin humide plus longtemps.", "it": "Keeps your garden moist longer.", "pt": "Keeps your garden moist longer.", "ja": "庭の潤いを長く保ちます。", "ko": "정원을 더 오랫동안 촉촉하게 유지합니다.", "pl": "Utrzymuje wilgoć w ogrodzie na dłużej.", "nl": "Houdt uw tuin langer vochtig.", "tr": "Bahçenizin daha uzun süre nemli kalmasını sağlar."],
        "item.giesscan_pro.name": ["de": "Gießkanne Pro", "en": "Watering Can Pro", "es": "Regadera Pro", "fr": "Arrosoir Pro", "it": "Watering Can Pro", "pt": "Watering Can Pro", "ja": "じょうろプロ", "ko": "물뿌리개 프로", "pl": "Konewka Pro", "nl": "Gieter Pro", "tr": "Sulama Kabı Pro"],
        "item.giesscan_pro.usage": ["de": "Automatischer Effekt.", "en": "Automatic effect.", "es": "Efecto automático.", "fr": "Effet automatique.", "it": "Automatic effect.", "pt": "Automatic effect.", "ja": "自動効果。", "ko": "자동 효과.", "pl": "Efekt automatyczny.", "nl": "Automatisch effect.", "tr": "Otomatik efekt."],
        "item.gluecks_segen.description": ["de": "Ein Segen, der 24h lang das Wachstum aller Pflanzen verdoppelt.", "en": "A blessing that doubles the growth of all plants for 24h.", "es": "Una bendición que duplica el crecimiento de todas las plantas durante 24h.", "fr": "Une bénédiction qui double la croissance de toutes les plantes pendant 24h.", "it": "A blessing that doubles the growth of all plants for 24h.", "pt": "Uma bênção que duplica o crescimento de todas as plantas durante 24h.", "ja": "24時間すべての植物の成長を2倍にする祝福。", "ko": "24시간 동안 모든 식물의 성장이 두 배로 늘어나는 축복입니다.", "pl": "Błogosławieństwo podwajające wzrost wszystkich roślin na 24h.", "nl": "Een zegen die de groei van alle planten 24 uur lang verdubbelt.", "tr": "24 saat boyunca tüm bitkilerin büyümesini ikiye katlayan bir nimet."],
        "item.gluecks_segen.name": ["de": "Glücks-Segen", "en": "Luck's Blessing", "es": "Bendición de la Suerte", "fr": "Bénédiction de chance", "it": "Luck's Blessing", "pt": "Bênção da sorte", "ja": "幸運の祝福", "ko": "행운의 축복", "pl": "Błogosławieństwo szczęścia", "nl": "De zegen van geluk", "tr": "Şansın Kutsaması"],
        "item.gluecks_segen.usage": ["de": "Wird sofort aktiv und segnet deinen Garten mit schnellem Wachstum.", "en": "Becomes active immediately and blesses your garden with rapid growth.", "es": "Wird sofort aktiv und segnet deinen Garten mit schnellem Wachstum.", "fr": "S'active immédiatement et bénit ton jardin d'une croissance rapide.", "it": "Becomes active immediately and blesses your garden with rapid growth.", "pt": "Ativa imediatamente e abençoa o teu jardim com crescimento rápido.", "ja": "すぐに活発になり、庭を急速に成長させます。", "ko": "즉시 활성화되어 정원이 빠르게 성장하도록 축복합니다.", "pl": "Natychmiast staje się aktywny i błogosławi Twój ogród szybkim wzrostem.", "nl": "Wordt onmiddellijk actief en zegent uw tuin met snelle groei.", "tr": "Hemen aktif hale gelir ve bahçenize hızlı bir büyüme sağlar."],
        "item.goldener_schluessel.description": ["de": "Ein wertvoller Schlüssel, der das volle Wachstumspotenzial deines Gartens für eine Woche entriegelt.", "en": "A valuable key that unlocks the full growth potential of your garden for one week.", "es": "Una valiosa llave que desbloquea el potencial de crecimiento completo de tu jardín durante una semana.", "fr": "Une précieuse clé qui déverrouille le plein potentiel de croissance de ton jardin pendant une semaine.", "it": "A valuable key that unlocks the full growth potential of your garden for one week.", "pt": "Uma chave valiosa que desbloqueia todo o potencial de crescimento do teu jardim durante uma semana.", "ja": "あなたの庭の潜在的な成長の可能性を 1 週間解放する貴重な鍵です。", "ko": "일주일 동안 정원의 성장 잠재력을 최대한 발휘할 수 있는 귀중한 열쇠입니다.", "pl": "Cenny klucz, który odblokowuje pełny potencjał wzrostu Twojego ogrodu na tydzień.", "nl": "Een waardevolle sleutel die gedurende één week het volledige groeipotentieel van uw tuin ontsluit.", "tr": "Bahçenizin bir hafta boyunca tam büyüme potansiyelini ortaya çıkaracak değerli bir anahtar."],
        "item.goldener_schluessel.name": ["de": "Goldener Schlüssel", "en": "Golden Key", "es": "Llave Dorada", "fr": "Clé dorée", "it": "Golden Key", "pt": "Chave dourada", "ja": "黄金の鍵", "ko": "황금열쇠", "pl": "Złoty klucz", "nl": "Gouden sleutel", "tr": "Altın Anahtar"],
        "item.goldener_schluessel.usage": ["de": "Wird sofort aktiv und öffnet die Tür zu raschem Wachstum.", "en": "Becomes active immediately and opens the door to rapid growth.", "es": "Wird sofort aktiv und öffnet die Tür zu raschem Wachstum.", "fr": "S'active immédiatement et ouvre la porte à une croissance rapide.", "it": "Becomes active immediately and opens the door to rapid growth.", "pt": "Ativa imediatamente e abre a porta para o crescimento rápido.", "ja": "即戦力となり、急成長への扉が開きます。", "ko": "즉시 활성화되어 급속한 성장의 문을 열어줍니다.", "pl": "Staje się aktywny natychmiast i otwiera drzwi do szybkiego wzrostu.", "nl": "Wordt onmiddellijk actief en opent de deur naar snelle groei.", "tr": "Hemen aktif hale gelir ve hızlı büyümeye kapı açar."],
        "item.streak_schutz.description": ["de": "Schützt deine Streaks 48h lang.", "en": "Protects your streaks for 48h.", "es": "Protege tus rachas durante 48h.", "fr": "Protège tes séries pendant 48h.", "it": "Protects your streaks for 48h.", "pt": "Protege as tuas sequências durante 48h.", "ja": "あなたの筋を48時間保護します。", "ko": "48시간 동안 연속 기록을 보호합니다.", "pl": "Chroni pasma przez 48h.", "nl": "Beschermt je strepen gedurende 48 uur.", "tr": "Çizgilerinizi 48 saat boyunca korur."],
