        "item.streak_schutz.usage": ["de": "Automatischer Schutz.", "en": "Automatic protection.", "es": "Protección automática.", "fr": "Protection automatique.", "it": "Automatic protection.", "pt": "Proteção automática.", "ja": "自動保護。", "ko": "자동 보호.", "pl": "Automatyczna ochrona.", "nl": "Automatische bescherming.", "tr": "Otomatik koruma."],
        "item.tier_freund.description": ["de": "Bestäubt 3 Pflanzen mit einem Mini-Level-Boost.", "en": "Pollinates 3 plants with a mini level boost.", "es": "Poliniza 3 plantas con un mini impulso de nivel.", "fr": "Pollinise 3 plantes avec un mini boost de niveau.", "it": "Pollinates 3 plants with a mini level boost.", "pt": "Poliniza 3 plantas com um mini boost de nível.", "ja": "ミニレベルブーストで3つの植物に受粉します。", "ko": "미니 레벨 부스트로 3개의 식물에 수분을 공급합니다.", "pl": "Zapyla 3 rośliny z mini-zwiększeniem poziomu.", "nl": "Bestuift 3 planten met een mini-niveauboost.", "tr": "Mini seviye desteğiyle 3 bitkiyi tozlaştırır."],
