        "item.tier_freund.usage": ["de": "Wird sofort aktiv und ruft kleine Helfer in den Garten.", "en": "Becomes active immediately and calls little helpers to the garden.", "es": "Wird sofort aktiv und ruft kleine Helfer in den Garten.", "fr": "S'active immédiatement et appelle de petits auxiliaires dans le jardin.", "it": "Becomes active immediately and calls little helpers to the garden.", "pt": "Ativa imediatamente e chama pequenos ajudantes para o jardim.", "ja": "すぐに活発になり、小さなお手伝いさんを庭に呼びます。", "ko": "즉시 활성화되어 정원에 작은 도우미를 불러옵니다.", "pl": "Natychmiast staje się aktywny i przywołuje małych pomocników do ogrodu.", "nl": "Wordt onmiddellijk actief en roept kleine helpers naar de tuin.", "tr": "Hemen aktif hale gelir ve minik yardımcılarını bahçeye çağırır."],
        "item.waechter_turm.description": ["de": "Rettet eine Pflanze einmalig vor dem Austrocknen und dem sicheren Tod.", "en": "Saves a plant once from drying out and certain death.", "es": "Salva una planta una vez de secarse y de una muerte segura.", "fr": "Sauve une plante une fois du dessèchement et d'une mort certaine.", "it": "Salva una pianta una volta dall'essiccazione e da morte certa.", "pt": "Salva uma planta uma vez de secar e de morte certa.", "ja": "植物を乾燥と確実な死から一度救います。", "ko": "식물이 마르고 죽는 것을 한 번만 방지합니다.", "pl": "Raz ratuje roślinę przed wysychaniem i pewną śmiercią.", "nl": "Voorkomt een plant één keer uitdrogen en een zekere dood.", "tr": "Bir bitkiyi bir kez kurumaktan ve kesin ölümden kurtarır."],
        "item.waechter_turm.name": ["de": "Wächter-Turm", "en": "Guardian Tower", "es": "Torre Guardiana", "fr": "Tour gardienne", "it": "Guardian Tower", "pt": "Torre guardiã", "ja": "ガーディアンタワー", "ko": "가디언 타워", "pl": "Wieża Strażnicza", "nl": "Guardian-toren", "tr": "Muhafız Kulesi"],
        "item.waechter_turm.usage": ["de": "Tippe auf die Pflanze, die du mit dem Turm schützen möchtest.", "en": "Tap on the plant you want to protect with the tower.", "es": "Tippe auf die Pflanze, die du mit dem Turm schützen möchtest.", "fr": "Appuie sur la plante que tu veux protéger avec la tour.", "it": "Tap on the plant you want to protect with the tower.", "pt": "Toca na planta que queres proteger com a torre.", "ja": "タワーで守りたい植物をタップします。", "ko": "타워로 보호하고 싶은 식물을 탭하세요.", "pl": "Kliknij roślinę, którą chcesz chronić za pomocą wieży.", "nl": "Tik op de plant die je wilt beschermen met de toren.", "tr": "Kuleyle korumak istediğiniz bitkiye dokunun."],
        "item.wunder_wasser.description": ["de": "Rettet eine vertrocknete Pflanze sofort.", "en": "Rescues a dried plant immediately.", "es": "Rescata una planta seca inmediatamente.", "fr": "Sauve immédiatement une plante desséchée.", "it": "Rescues a dried plant immediately.", "pt": "Salva imediatamente uma planta ressecada.", "ja": "枯れた植物をすぐに救出します。", "ko": "말린 식물을 즉시 구출합니다.", "pl": "Natychmiast ratuje wysuszoną roślinę.", "nl": "Redt een gedroogde plant onmiddellijk.", "tr": "Kurumuş bir bitkiyi anında kurtarır."],
