        "item.xp_boost.description": ["de": "Verdoppelt XP für 12 Stunden.", "en": "Doubles XP for 12 hours.", "es": "Duplica la XP durante 12 horas.", "fr": "Double les XP pendant 12 heures.", "it": "Doubles XP for 12 hours.", "pt": "Duplica o XP durante 12 horas.", "ja": "12時間XPが2倍になります。", "ko": "12시간 동안 XP가 두 배로 늘어납니다.", "pl": "Podwaja XP na 12 godzin.", "nl": "Verdubbelt XP gedurende 12 uur.", "tr": "12 saat boyunca XP'yi iki katına çıkarır."],
