        "item.xp_boost.usage": ["de": "Wird im Garten aktiviert.", "en": "Activate in the garden.", "es": "Activa en el jardín.", "fr": "Active dans le jardin.", "it": "Activate in the garden.", "pt": "Ativa no jardim.", "ja": "庭で活動します。", "ko": "정원에서 활성화하세요.", "pl": "Aktywuj w ogrodzie.", "nl": "Activeer in de tuin.", "tr": "Bahçede etkinleştirin."],
        "item.zauberstab.description": ["de": "Ein magischer Stab, der 3 Tage lang automatisch das Unkraut wegzaubert.", "en": "A magic wand that automatically removes weeds for 3 days.", "es": "Una varita mágica que elimina automáticamente las malas hierbas durante 3 días.", "fr": "Une baguette magique qui élimine automatiquement les mauvaises herbes pendant 3 jours.", "it": "Una bacchetta magica che rimuove automaticamente le erbacce per 3 giorni.", "pt": "Uma varinha mágica que remove automaticamente as ervas daninhas durante 3 dias.", "ja": "3日間自動で雑草を除去してくれる魔法の杖。", "ko": "3일 동안 자동으로 잡초를 제거해 주는 마술 지팡이입니다.", "pl": "Magiczna różdżka, która automatycznie usuwa chwasty na 3 dni.", "nl": "Een toverstaf die 3 dagen lang automatisch onkruid verwijdert.", "tr": "Yabani otları 3 gün boyunca otomatik olarak temizleyen sihirli bir değnek."],
        "item.zauberstab.name": ["de": "Zauberstab", "en": "Magic Wand", "es": "Varita Mágica", "fr": "Baguette magique", "it": "Magic Wand", "pt": "Varinha mágica", "ja": "魔法の杖", "ko": "마술 지팡이", "pl": "Magiczna różdżka", "nl": "Toverstaf", "tr": "Sihirli değnek"],
        "item.zauberstab.usage": ["de": "Wird sofort aktiv und lässt Unkraut wie von Geisterhand verschwinden.", "en": "Becomes active immediately and makes weeds disappear as if by magic.", "es": "Se activa de inmediato y hace desaparecer las malas hierbas como por arte de magia.", "fr": "S\'active immédiatement et fait disparaître les mauvaises herbes comme par enchantement.", "it": "Si attiva immediatamente e fa sparire le erbacce come per magia.", "pt": "Ativa imediatamente e faz as ervas daninhas desaparecer como por magia.", "ja": "すぐに活性化して、まるで魔法のように雑草を消し去ります。", "ko": "즉시 활성화되어 마법처럼 잡초를 사라지게 합니다.", "pl": "Natychmiast staje się aktywny i sprawia, że ​​chwasty znikają jak za dotknięciem czarodziejskiej różdżki.", "nl": "Wordt direct actief en laat onkruid als bij toverslag verdwijnen.", "tr": "Hemen aktif hale gelir ve yabani otların sanki sihirli bir değnekmiş gibi yok olmasını sağlar."],
        "item.zeitkapsel.description": ["de": "Friert eine Pflanze ein – kein Verfall für 3 Tage.", "en": "Freezes a plant – no decay for 3 days.", "es": "Congela una planta – sin deterioro durante 3 días.", "fr": "Gèle une plante – pas de dégradation pendant 3 jours.", "it": "Freezes a plant – no decay for 3 days.", "pt": "Congela uma planta – sem degradação durante 3 dias.", "ja": "植物を凍結します – 3日間腐敗しません。", "ko": "식물을 얼리면 3일 동안 부패하지 않습니다.", "pl": "Zamraża roślinę – brak rozkładu przez 3 dni.", "nl": "Bevriest een plant – geen verval gedurende 3 dagen.", "tr": "Bir bitkiyi dondurur – 3 gün boyunca çürüme olmaz."],
        "item.zeitkapsel.name": ["de": "Zeitkapsel", "en": "Time Capsule", "es": "Cápsula del Tiempo", "fr": "Capsule temporelle", "it": "Time Capsule", "pt": "Cápsula do tempo", "ja": "タイムカプセル", "ko": "타임캡슐", "pl": "Kapsuła Czasu", "nl": "Tijdcapsule", "tr": "Zaman Kapsülü"],
        "item.zeitkapsel.usage": ["de": "Wird sofort aktiv und stoppt den Verfall aller Pflanzen.", "en": "Becomes active immediately and stops decay for all plants.", "es": "Wird sofort aktiv und stoppt den Verfall aller Pflanzen.", "fr": "S'active immédiatement et stoppe la dégradation de toutes les plantes.", "it": "Becomes active immediately and stops decay for all plants.", "pt": "Ativa imediatamente e para a degradação de todas as plantas.", "ja": "すぐに活性化し、すべての植物の腐敗を止めます。", "ko": "즉시 활성화되어 모든 식물의 부패를 멈춥니다.", "pl": "Staje się aktywny natychmiast i zatrzymuje rozkład wszystkich roślin.", "nl": "Wordt onmiddellijk actief en stopt het verval van alle planten.", "tr": "Hemen aktif hale gelir ve tüm bitkilerde çürümeyi durdurur."],
        "key": ["de": "Deutsch", "en": "German", "es": "Español", "fr": "Français", "it": "Italiano", "pt": "Português", "ja": "ドイツ語", "ko": "독일 사람", "pl": "niemiecki", "nl": "Duits", "tr": "Almanca"],
        "leben.regel1": ["de": "Gieße deine Pflanzen täglich um Leben zu behalten", "en": "Water your plants daily to keep your lives", "es": "Riega tus plantas diariamente para conservar tus vidas", "fr": "Arrose tes plantes quotidiennement pour garder tes vies", "it": "Water your plants daily to keep your lives", "pt": "Rega as tuas plantas diariamente para manter as vidas", "ja": "命を守るために毎日植物に水をあげましょう", "ko": "생명을 유지하려면 매일 식물에 물을 주세요", "pl": "Podlewaj rośliny codziennie, aby zachować życie", "nl": "Geef uw planten dagelijks water om uw leven te behouden", "tr": "Yaşamınızı sürdürmek için bitkilerinizi günlük olarak sulayın"],
        "leben.regel2": ["de": "Stirbt eine Pflanze, verlierst du ein Leben", "en": "If a plant dies, you lose one life", "es": "Si una planta muere, pierdes una vida", "fr": "Si une plante meurt, tu perds une vie", "it": "If a plant dies, you lose one life", "pt": "Se uma planta morrer, perdes uma vida", "ja": "植物が枯れると命が一つ失われる", "ko": "식물이 죽으면 생명 하나를 잃습니다.", "pl": "Jeśli roślina obumrze, tracisz jedno życie", "nl": "Als een plant sterft, verlies je één leven", "tr": "Bir bitki ölürse bir can kaybedersiniz"],
        "leben.regel3": ["de": "Bei 0 Leben werden alle Pflanzen gelöscht", "en": "At 0 lives, all plants are deleted", "es": "Con 0 vidas, todas las plantas son eliminadas", "fr": "À 0 vie, toutes les plantes sont supprimées", "it": "At 0 lives, all plants are deleted", "pt": "Com 0 vidas, todas as plantas são eliminadas", "ja": "ライフが0になるとすべての植物が削除されます", "ko": "생명이 0이 되면 모든 식물이 삭제됩니다.", "pl": "Przy 0 życiach wszystkie rośliny są usuwane", "nl": "Bij 0 levens worden alle planten verwijderd", "tr": "0 yaşamda tüm bitkiler silinir"],
