        "onboarding_benachrichtigung_blase": ["de": "Soll ich dich an deine Gewohnheiten erinnern? So vergisst du nie zu gießen!", "en": "Should I remind you of your habits? That way you'll never forget to water!", "es": "¿Quieres que te recuerde tus hábitos? ¡Así nunca olvidarás regar!", "fr": "Dois-je te rappeler tes habitudes ? Ainsi, tu n'oublieras jamais d'arroser !", "it": "Should I remind you of your habits? That way you'll never forget to water!", "pt": "Queres que te lembre dos teus hábitos? Assim nunca te esquecerás de regar!", "ja": "あなたの習慣を思い出させたほうがいいでしょうか？そうすれば水やりを忘れることがなくなりますよ！", "ko": "당신의 습관을 상기시켜 드려야 할까요? 그렇게 하면 물 주는 것을 결코 잊지 않을 것입니다!", "pl": "Mam ci przypomnieć o twoich nawykach? Dzięki temu nigdy nie zapomnisz o podlaniu!", "nl": "Moet ik je aan je gewoontes herinneren? Zo vergeet je nooit meer water te geven!", "tr": "Sana alışkanlıklarını hatırlatmalı mıyım? Böylece sulamayı asla unutmayacaksınız!"],
        "onboarding_benachrichtigung_einstellungen": ["de": "In Einstellungen öffnen", "en": "Open in Settings", "es": "Abrir en Ajustes", "fr": "Ouvrir les paramètres", "it": "Open in Settings", "pt": "Abrir nas Definições", "ja": "設定で開く", "ko": "설정에서 열기", "pl": "Otwórz w Ustawieniach", "nl": "Openen in Instellingen", "tr": "Ayarlar'da aç"],
        "onboarding_benachrichtigung_erlauben": ["de": "ERLAUBEN", "en": "ALLOW", "es": "PERMITIR", "fr": "AUTORISER", "it": "ALLOW", "pt": "PERMITIR", "ja": "許可する", "ko": "허용하다", "pl": "UMOŻLIWIĆ", "nl": "TOESTAAN", "tr": "İZİN VERMEK"],
        "onboarding_benachrichtigung_spaeter": ["de": "Später vielleicht", "en": "Maybe later", "es": "Tal vez más tarde", "fr": "Plus tard peut-être", "it": "Maybe later", "pt": "Talvez mais tarde", "ja": "たぶん後で", "ko": "어쩌면 나중에", "pl": "Może później", "nl": "Misschien later", "tr": "Belki daha sonra"],
        "notification.evening.1.body": ["de": "Du hast noch %d %@! Komm vorbei, bevor der Tag endet.", "en": "You still have %d %@! Stop by before the day ends.", "es": "¡Aún tienes %d %@! Pasa por aquí antes de que acabe el día.", "fr": "Tu as encore %d %@ ! Viens avant la fin de la journée.", "it": "Hai ancora %d %@! Passa prima che finisca la giornata.", "pt": "Ainda tens %d %@! Aparece antes que o dia acabe.", "ja": "まだ %d %@ が残っています!一日が終わる前にお立ち寄りください。", "ko": "아직 %d%@이 있습니다! 하루가 끝나기 전에 들러보세요.", "pl": "Nadal masz %d %@! Zatrzymaj się, zanim dzień się skończy.", "nl": "Je hebt nog steeds %d %@! Kom langs voordat de dag voorbij is.", "tr": "Hala %d %@'ınız var! Gün bitmeden uğrayın."],
        "notification.evening.1.title": ["de": "Dein Garten wartet", "en": "Your garden is waiting", "es": "Tu jardín te espera", "fr": "Ton jardin t'attend", "it": "Il tuo giardino ti aspetta", "pt": "O teu jardim espera por ti", "ja": "あなたの庭が待っています", "ko": "당신의 정원이 기다리고 있습니다", "pl": "Twój ogród czeka", "nl": "Je tuin wacht", "tr": "Bahçeniz sizi bekliyor"],
        "notification.evening.2.body": ["de": "Vergiss nicht auf deine Pflanzen! %d %@ braucht heute noch Wasser.", "en": "Don't forget your plants! %d %@ still needs water today.", "es": "¡No olvides tus plantas! %d %@ todavía necesita agua hoy.", "fr": "N'oublie pas tes plantes ! %d %@ a encore besoin d'eau aujourd'hui.", "it": "Non dimenticare le tue piante! %d %@ ha ancora bisogno d'acqua oggi.", "pt": "Não te esqueças das tuas plantas! %d %@ ainda precisa de água hoje.", "ja": "植物も忘れずに！ %d %@ は今日も水が必要です。", "ko": "당신의 식물을 잊지 마세요! %d %@ 오늘도 여전히 물이 필요합니다.", "pl": "Nie zapomnij o swoich roślinach! %d %@ nadal dzisiaj potrzebuje wody.", "nl": "Vergeet je planten niet! %d %@ heeft vandaag nog steeds water nodig.", "tr": "Bitkilerinizi unutmayın! %d %@ bugün hâlâ suya ihtiyaç duyuyor."],
        "notification.evening.2.title": ["de": "Ein letzter Blick?", "en": "One last look?", "es": "¿Un último vistazo?", "fr": "Un dernier coup d'œil ?", "it": "Un'ultima occhiata?", "pt": "Um último olhar?", "ja": "最後にもう一度見てみましょう？", "ko": "마지막으로 살펴볼까요?", "pl": "Ostatnie spojrzenie?", "nl": "Nog een laatste blik?", "tr": "Son bir bakış mı?"],
        "notification.evening.3.body": ["de": "Der Abend bricht an... und %d %@ rufen nach dir!", "en": "Evening falls... and %d %@ are calling for you!", "es": "Cae la noche... ¡y %d %@ te están llamando!", "fr": "Le soir tombe... et %d %@ t'appellent !", "it": "Scende la sera... e %d %@ ti chiamano!", "pt": "A noite cai... e %d %@ chamam por ti!", "ja": "夕方になります...そして %d %@ があなたを呼んでいます!", "ko": "저녁이 되니... %d %@이(가) 당신을 부르고 있습니다!", "pl": "Zapada wieczór... i %d %@ wzywa Cię!", "nl": "De avond valt... en %d %@ roept je!", "tr": "Akşam düşüyor... ve %d %@ sizi çağırıyor!"],
        "notification.evening.3.title": ["de": "Stille im Garten", "en": "Silence in the garden", "es": "Silencio en el jardín", "fr": "Silence dans le jardin", "it": "Silenzio nel giardino", "pt": "Silêncio no jardim", "ja": "庭の静寂", "ko": "정원의 침묵", "pl": "Cisza w ogrodzie", "nl": "Stilte in de tuin", "tr": "Bahçede sessizlik"],
        "notification.morning.1.body": ["de": "Zeit für Gewohnheiten! Dein höchster Streak ist %d. Lass uns weiter wachsen!", "en": "Time for habits! Your highest streak is %d. Let's keep growing!", "es": "¡Hora de los hábitos! Tu mejor racha es %d. ¡Sigamos creciendo!", "fr": "L'heure des habitudes ! Ta meilleure série est %d. Continuons à grandir !", "it": "È l'ora delle abitudini! La tua serie migliore è %d. Continuiamo a crescere!", "pt": "Hora dos hábitos! O teu melhor streak é %d. Vamos continuar a crescer!", "ja": "習慣の時間です！あなたの最高連続記録は %d です。これからも成長していきましょう！", "ko": "습관이 필요한 시간! 가장 높은 연속 기록은 %d입니다. 계속 성장하자!", "pl": "Czas na nawyki! Twoja najwyższa passa to %d. Rozwijajmy się dalej!", "nl": "Tijd voor gewoontes! Je hoogste reeks is %d. Laten we blijven groeien!", "tr": "Alışkanlık zamanı! En yüksek seriniz %d. Büyümeye devam edelim!"],
        "notification.morning.1.title": ["de": "Guten Morgen!", "en": "Good morning!", "es": "¡Buenos días!", "fr": "Bonjour !", "it": "Buongiorno!", "pt": "Bom dia!", "ja": "おはよう！", "ko": "좋은 아침이에요!", "pl": "Dzień dobry!", "nl": "Goedemorgen!", "tr": "Günaydın!"],
        "notification.morning.2.body": ["de": "Ein neuer Start! Baue deinen Streak von %d weiter aus.", "en": "A fresh start! Keep building your streak of %d.", "es": "¡Un nuevo comienzo! Sigue aumentando tu racha de %d.", "fr": "Un nouveau départ ! Continue de construire ta série de %d.", "it": "Un nuovo inizio! Continua a costruire la tua serie di %d.", "pt": "Um novo começo! Continua a aumentar o teu streak de %d.", "ja": "新たなスタート！ %d の連続記録を築き続けてください。", "ko": "새로운 시작! %d 연속 연속 기록을 계속 쌓아보세요.", "pl": "Nowy początek! Kontynuuj swoją passę %d.", "nl": "Een nieuw begin! Blijf je streak van %d opbouwen.", "tr": "Yeni bir başlangıç! %d serisini oluşturmaya devam edin."],
        "notification.morning.2.title": ["de": "Erfrischt aufwachen", "en": "Wake up refreshed", "es": "Despierta con energía", "fr": "Réveille-toi en forme", "it": "Svegliati rinfrescato", "pt": "Acorda revigorado", "ja": "すっきり目覚める", "ko": "상쾌하게 일어나세요", "pl": "Obudź się wypoczęty", "nl": "Word uitgerust wakker", "tr": "Yenilenmiş olarak uyanın"],
        "notification.morning.3.body": ["de": "Dein Garten gedeiht! %d Tage harte Arbeit warten auf Fortsetzung.", "en": "Your garden thrives! %d days of hard work await continuation.", "es": "¡Tu jardín prospera! %d días de duro trabajo esperan continuar.", "fr": "Ton jardin prospère ! %d jours de dur labeur t'attendent.", "it": "Il tuo giardino prospera! %d giorni di duro lavoro aspettano di essere continuati.", "pt": "O teu jardim prospera! %d dias de trabalho árduo aguardam continuação.", "ja": "あなたの庭は繁栄します！ %d 日のハードワークが継続を待っています。", "ko": "당신의 정원이 번성합니다! %d일간의 노력이 계속될 것입니다.", "pl": "Twój ogród kwitnie! %d dni ciężkiej pracy czeka na kontynuację.", "nl": "Uw tuin bloeit! %d dagen hard werken wachten op voortzetting.", "tr": "Bahçeniz gelişiyor! %d günlük sıkı çalışma devam etmeyi bekliyor."],
        "notification.morning.3.title": ["de": "Neuer Tag, neues Glück", "en": "New day, new luck", "es": "Nuevo día, nueva suerte", "fr": "Nouveau jour, nouvelle chance", "it": "Nuovo giorno, nuova fortuna", "pt": "Novo dia, nova sorte", "ja": "新しい日、新しい幸運", "ko": "새로운 날, 새로운 행운", "pl": "Nowy dzień, nowe szczęście", "nl": "Nieuwe dag, nieuw geluk", "tr": "Yeni gün, yeni şans"],
        "notification.streak.1.body": ["de": "Ohje! Wenn du jetzt nachlässt, stirbt die Pflanze und du verlierst %d Tage Streak.", "en": "Oh dear! If you slack now, the plant dies and you lose a %d-day streak.", "es": "¡Oh no! Si aflojas ahora, la planta muere y pierdes una racha de %d días.", "fr": "Oh là là ! Si tu relâches maintenant, la plante meurt et tu perds %d jours de série.", "it": "Oh no! Se ti arrendi ora, la pianta muore e perdi %d giorni di serie.", "pt": "Oh não! Se vacilares agora, a planta morre e perdes um streak de %d dias.", "ja": "まあ！ここで怠けると、植物は枯れてしまい、%d 日連続で損失が発生します。", "ko": "이런! 지금 느슨해지면 식물이 죽고 %d일 연속 기록을 잃게 됩니다.", "pl": "Och kochanie! Jeśli teraz zwolnisz, roślina umrze i stracisz passę %d-dniową.", "nl": "O lief! Als je nu verslapt, sterft de plant en verlies je een streak van %d dagen.", "tr": "Ah hayatım! Şimdi gevşerseniz, bitki ölür ve %d günlük seriyi kaybedersiniz."],
        "notification.streak.1.title": ["de": "Achtung, Streak in Gefahr!", "en": "Watch out, streak in danger!", "es": "¡Cuidado, racha en peligro!", "fr": "Attention, série en danger !", "it": "Attenzione, serie in pericolo!", "pt": "Cuidado, streak em perigo!", "ja": "気をつけて、連続危険！", "ko": "조심하세요, 위험에 처해있습니다!", "pl": "Uważaj, passa w niebezpieczeństwie!", "nl": "Pas op, streak in gevaar!", "tr": "Dikkat, tehlikede çizgi!"],
        "notification.streak.2.body": ["de": "Deine Gewohnheit steht auf der Kippe. Rette jetzt deine %d-Tage harte Arbeit!", "en": "Your habit is on the brink. Save your %d days of hard work now!", "es": "Tu hábito está en peligro. ¡Salva ahora tus %d días de duro trabajo!", "fr": "Ton habitude est en péril. Sauve maintenant tes %d jours de dur labeur !", "it": "La tua abitudine è a rischio. Salva ora i tuoi %d giorni di duro lavoro!", "pt": "O teu hábito corre perigo. Salva agora os teus %d dias de trabalho árduo!", "ja": "あなたの習慣は瀬戸際にあります。 %d 日間のハードワークを今すぐ節約しましょう!", "ko": "당신의 습관이 위기에 처해 있습니다. 지금 %d일간 열심히 일한 시간을 절약하세요!", "pl": "Twój nawyk jest na krawędzi. Zaoszczędź teraz %d dni ciężkiej pracy!", "nl": "Je gewoonte staat op de rand. Bespaar nu uw %d dagen hard werken!", "tr": "Alışkanlığınız eşiğinde. %d günlük sıkı çalışmanızı şimdi kaydedin!"],
        "notification.streak.2.title": ["de": "%@ welkt gleich...", "en": "%@ is about to wither...", "es": "%@ está a punto de marchitarse...", "fr": "%@ est sur le point de faner...", "it": "%@ sta per appassire...", "pt": "%@ está quase a murchar...", "ja": "%@ は枯れそうです...", "ko": "%@이(가) 시들려고 합니다...", "pl": "%@ wkrótce uschnie...", "nl": "%@ staat op het punt te verwelken...", "tr": "%@ solmak üzere..."],
        "notification.streak.3.body": ["de": "Du bist schon %d Tage dabei! Lass es nicht umsonst gewesen sein.", "en": "You've been at it for %d days! Don't let it be for nothing.", "es": "¡Llevas %d días en esto! No dejes que sea en vano.", "fr": "Ça fait déjà %d jours ! Ne laisse pas ça être pour rien.", "it": "Sei già a %d giorni! Non far sì che sia tutto inutile.", "pt": "Já estás nisto há %d dias! Não deixes que seja em vão.", "ja": "%d 日間続けています!無駄にしないでください。", "ko": "%d일 동안 이 일을 하셨습니다! 헛된 일이 되지 않도록 하십시오.", "pl": "Zajmujesz się tym od %d dni! Nie pozwól, żeby to poszło na marne.", "nl": "Je bent al %d dagen bezig! Laat het niet voor niets zijn.", "tr": "%d gündür bu iştesin! Boşuna olmasına izin vermeyin."],
        "notification.streak.3.title": ["de": "Bleib dran für %@!", "en": "Keep it up for %@!", "es": "¡Sigue así por %@!", "fr": "Continue pour %@ !", "it": "Continua così per %@!", "pt": "Continua por %@!", "ja": "%@まで頑張ってください!", "ko": "%@ 동안 계속 힘내세요!", "pl": "Tak trzymaj przez %@!", "nl": "Ga zo door voor %@!", "tr": "%@ için böyle devam edin!"],
        "notification.wait.1.body": ["de": "Schon %d Stunden ohne Pflege. Schau doch kurz im Garten vorbei!", "en": "Already %d hours without care. Just drop by the garden briefly!", "es": "Ya van %d horas sin cuidados. ¡Pasa un momento por el jardín!", "fr": "Déjà %d heures sans soins. Fais un petit tour dans le jardin !", "it": "Già %d ore senza cure. Fai un salto nel giardino!", "pt": "Já %d horas sem cuidados. Dá um salto ao jardim!", "ja": "気にせずにすでに %d 時間経過しています。ぜひちょっとお庭にお立ち寄りください！", "ko": "이미 %d시간 동안 신경 쓰지 않았습니다. 잠시 정원에 들러보세요!", "pl": "Już %d godzin bez opieki. Wpadnij na chwilę do ogrodu!", "nl": "Al %d uur zonder zorg. Kom gewoon even langs in de tuin!", "tr": "Zaten %d saat bakımsız kaldım. Kısa bir süreliğine bahçeye uğramanız yeterli!"],
        "notification.wait.1.title": ["de": "%@ vermisst dich!", "en": "%@ misses you!", "es": "¡%@ te echa de menos!", "fr": "%@ s'ennuie de toi !", "it": "%@ sente la tua mancanza!", "pt": "%@ tem saudades tuas!", "ja": "%@ に会いたいです!", "ko": "%@님이 그리워요!", "pl": "%@ tęskni za tobą!", "nl": "%@ mist je!", "tr": "%@ seni özlüyor!"],
        "notification.wait.2.body": ["de": "Die Zeit rennt! Erledige deine Gewohnheit (%d Stunden vergangen).", "en": "Time is flying! Complete your habit (%d hours passed).", "es": "¡El tiempo vuela! Completa tu hábito (han pasado %d horas).", "fr": "Le temps file ! Complète ton habitude (%d heures écoulées).", "it": "Il tempo vola! Completa la tua abitudine (%d ore passate).", "pt": "O tempo voa! Completa o teu hábito (%d horas passadas).", "ja": "時間はあっという間に過ぎます！習慣を完了してください (%d 時間が経過しました)。", "ko": "시간이 흐르고 있습니다! 습관을 완료하세요(%d시간 경과).", "pl": "Czas leci! Uzupełnij swój nawyk (minęło %d godzin).", "nl": "De tijd vliegt! Voltooi je gewoonte (%d uur verstreken).", "tr": "Zaman uçuyor! Alışkanlığınızı tamamlayın (%d saat geçti)."],
        "notification.wait.2.title": ["de": "Hallo? Zeit für %@!", "en": "Hello? Time for %@!", "es": "¿Hola? ¡Hora de %@!", "fr": "Allô ? C'est l'heure de %@ !", "it": "Ciao? È l'ora di %@!", "pt": "Olá? Hora de %@!", "ja": "こんにちは？ %@ の時間です!", "ko": "안녕하세요? %@을(를) 위한 시간입니다!", "pl": "Cześć? Czas na %@!", "nl": "Hallo? Tijd voor %@!", "tr": "Merhaba? %@ zamanı!"],
        "notification.wait.3.body": ["de": "Du hast noch %d Stunden Zeit, dich um deine Pflanze zu kümmern.", "en": "You have %d hours left to take care of your plant.", "es": "Aún tienes %d horas para cuidar de tu planta.", "fr": "Il te reste %d heures pour t'occuper de ta plante.", "it": "Hai ancora %d ore per prenderti cura della tua pianta.", "pt": "Ainda tens %d horas para cuidar da tua planta.", "ja": "植物の世話をする時間が残り %d 時間あります。", "ko": "식물을 돌볼 시간이 %d시간 남았습니다.", "pl": "Pozostało Ci %d godzin na zaopiekowanie się rośliną.", "nl": "Je hebt nog %d uur om voor je plant te zorgen.", "tr": "Tesisinizin bakımı için %d saatiniz kaldı."],
        "notification.wait.3.title": ["de": "Vergiss \"%@\" nicht!", "en": "Don't forget \"%@\"! ", "es": "¡No olvides \"%@\"! ", "fr": "N'oublie pas \"%@\" ! ", "it": "Non dimenticare \"%@\"! ", "pt": "Não te esqueças de \"%@\"! ", "ja": "忘れないで \"％@\"！", "ko": "\"%@\"을(를) 잊지 마세요!", "pl": "Nie zapomnij o „%@”!", "nl": "Vergeet \"%@\" niet!", "tr": "\"%@\" ifadesini unutmayın!"],
        "onboarding_benachrichtigung_status_abgelehnt": ["de": "Hinweis: Du hast Mitteilungen bereits deaktiviert. Um sie zu nutzen, musst du sie in den iOS-Einstellungen aktivieren.", "en": "Note: You have already disabled notifications. To use them, you must re-enable them in the iOS settings.", "es": "Nota: Ya has desactivado las notificaciones. Para usarlas, debes volver a activarlas en los ajustes de iOS.", "fr": "Note : tu as déjà désactivé les notifications. Pour les utiliser, tu dois les réactiver dans les réglages iOS.", "it": "Note: You have already disabled notifications. To use them, you must re-enable them in the iOS settings.", "pt": "Nota: Já desativaste as notificações. Para as usares, tens de as reativar nas definições do iOS.", "ja": "注: 通知はすでに無効になっています。これらを使用するには、iOS 設定で再度有効にする必要があります。", "ko": "참고: 이미 알림을 비활성화했습니다. 이를 사용하려면 iOS 설정에서 다시 활성화해야 합니다.", "pl": "Uwaga: wyłączyłeś już powiadomienia. Aby z nich skorzystać, należy je ponownie włączyć w ustawieniach iOS.", "nl": "Opmerking: je hebt meldingen al uitgeschakeld. Om ze te gebruiken, moet je ze opnieuw inschakelen in de iOS-instellingen.", "tr": "Not: Bildirimleri zaten devre dışı bıraktınız. Bunları kullanmak için iOS ayarlarında yeniden etkinleştirmeniz gerekir."],
        "onboarding_benachrichtigung_text": ["de": "Aktiviere Mitteilungen, um deinen Garten am Leben zu erhalten.", "en": "Enable notifications to keep your garden alive.", "es": "Activa las notificaciones para mantener vivo tu jardín.", "fr": "Active les notifications pour garder ton jardin en vie.", "it": "Enable notifications to keep your garden alive.", "pt": "Ativa as notificações para manter o teu jardim vivo.", "ja": "通知を有効にして庭を生き生きとさせましょう。", "ko": "정원에 생기를 불어넣으려면 알림을 활성화하세요.", "pl": "Włącz powiadomienia, aby Twój ogród żył.", "nl": "Schakel meldingen in om uw tuin levend te houden.", "tr": "Bahçenizi canlı tutmak için bildirimleri etkinleştirin."],
