        "onboarding_tutorial_2_text": ["de": "Deine Pflanzen wachsen von Bronze bis Diamant.", "en": "Your plants grow from Bronze to Diamond.", "es": "Tus plantas crecen de bronce a diamante.", "fr": "Tes plantes poussent de Bronze à Diamant.", "it": "Your plants grow from Bronze to Diamond.", "pt": "As tuas plantas crescem de Bronze a Diamante.", "ja": "植物はブロンズからダイヤモンドまで成長します。", "ko": "귀하의 식물은 브론즈에서 다이아몬드까지 자랍니다.", "pl": "Twoje rośliny rosną od brązu do diamentu.", "nl": "Je planten groeien van Brons naar Diamant.", "tr": "Bitkileriniz Bronz'dan Elmas'a kadar büyür."],
        "onboarding_tutorial_2_titel": ["de": "Sammle XP", "en": "Collect XP", "es": "Colecciona XP", "fr": "Collecte de l'XP", "it": "Collect XP", "pt": "Coleciona XP", "ja": "XPを集める", "ko": "XP 수집", "pl": "Zbieraj XP", "nl": "Verzamel XP", "tr": "XP topla"],
        "onboarding_tutorial_3_text": ["de": "Verdiene Coins und kaufe neue Pflanzen & Gegenstände.", "en": "Earn coins and buy new plants & items.", "es": "Gana monedas y compra nuevas plantas y objetos.", "fr": "Gagne des pièces et achète de nouvelles plantes et objets.", "it": "Earn coins and buy new plants & items.", "pt": "Ganha moedas e compra novas plantas e itens.", "ja": "コインを獲得し、新しい植物やアイテムを購入します。", "ko": "코인을 획득하고 새로운 식물과 아이템을 구입하세요.", "pl": "Zarabiaj monety i kupuj nowe rośliny i przedmioty.", "nl": "Verdien munten en koop nieuwe planten en items.", "tr": "Para kazanın ve yeni bitkiler ve eşyalar satın alın."],
        "onboarding_tutorial_3_titel": ["de": "Kaufe im Shop", "en": "Buy in the Shop", "es": "Compra en la tienda", "fr": "Achète dans la boutique", "it": "Buy in the Shop", "pt": "Compra na loja", "ja": "ショップで購入する", "ko": "상점에서 구매", "pl": "Kup w sklepie", "nl": "Koop in de winkel", "tr": "Mağazadan Satın Al"],
        "onboarding_tutorial_4_text": ["de": "Dekorationen geben dir kurzfristige Boni, aber nutze sie weise!", "en": "Decorations give you short-term bonuses, but use them wisely!", "es": "Las decoraciones te dan bonos a corto plazo, ¡pero úsalas con sabiduría!", "fr": "Les décorations te donnent des bonus à court terme, mais utilise-les avec sagesse !", "it": "Le decorazioni ti danno bonus a breve termine, ma usale con saggezza!", "pt": "As decorações dão-te bónus a curto prazo, mas usa-as com sabedoria!", "ja": "装飾は短期的なボーナスを与えますが、賢く使用してください。", "ko": "장식은 단기적인 보너스를 주지만 현명하게 사용하세요!", "pl": "Dekoracje dają krótkotrwałe premie, ale używaj ich mądrze!", "nl": "Decoraties geven je kortetermijnbonussen, maar gebruik ze verstandig!", "tr": "Dekorasyonlar size kısa vadeli bonuslar verir, ancak bunları akıllıca kullanın!"],
        "onboarding_tutorial_4_titel": ["de": "Deko & Belohnung", "en": "Decorations & Rewards", "es": "Decoraciones y recompensas", "fr": "Décorations et récompenses", "it": "Decorazioni e ricompense", "pt": "Decorações e recompensas", "ja": "装飾と報酬", "ko": "장식 및 보상", "pl": "Dekoracje i nagrody", "nl": "Decoraties en beloningen", "tr": "Dekorasyonlar ve Ödüller"],
        "onboarding_tutorial_5_text": ["de": "Gegenstände lassen Unkraut wachsen, das XP und Fortschritt blockiert.", "en": "Items can cause weeds to grow, hindering XP and progress.", "es": "Los objetos pueden hacer que crezcann malas hierbas, lo que dificulta la XP.", "fr": "Les objets peuvent faire de l'herbe pousse, ce qui freine l'XP.", "it": "Oggetti possono far crescere le erbacce, ostacolando l'XP.", "pt": "Os itens podem causar ervas daninhas, dificultando o XP.", "ja": "アイテムは雑草を生長させ、XP や進行を妨げる可能性があります。", "ko": "아이템으로 인해 잡초가 자라 XP와 진행을 방해할 수 있습니다.", "pl": "Przedmioty mogą powodować wzrost chwastów, utrudniając zdobywanie punktów doświadczenia i postęp.", "nl": "Items kunnen ervoor zorgen dat onkruid groeit, waardoor XP en voortgang worden belemmerd.", "tr": "Öğeler yabani otların büyümesine neden olarak XP'yi ve ilerlemeyi engelleyebilir."],
        "onboarding_tutorial_5_titel": ["de": "Achtung vor Unkraut!", "en": "Beware of Weeds!", "es": "¡Cuidado mit Unkraut!", "fr": "Attention aux mauvaises herbes !", "it": "Attenzione alle erbacce!", "pt": "Cuidado com as ervas daninhas!", "ja": "雑草に注意してください！", "ko": "잡초를 조심하세요!", "pl": "Uwaga na chwasty!", "nl": "Pas op voor onkruid!", "tr": "Otlara dikkat!"],
        "onboarding_tutorial_blase": ["de": "So funktioniert dein Garten!", "en": "This is how your garden works!", "es": "¡Así funciona tu jardín!", "fr": "Voici comment fonctionne ton jardin !", "it": "Ecco come funktioniert il tuo giardino!", "pt": "É assim que o teu jardim funciona!", "ja": "これがあなたの庭の仕組みです！", "ko": "이것이 당신의 정원이 작동하는 방식입니다!", "pl": "Tak działa Twój ogród!", "nl": "Zo werkt uw tuin!", "tr": "Bahçeniz böyle çalışır!"],
        "onboarding_tutorial_giessen_blase": ["de": "Zieh den Wassertropfen auf die Pflanze, um sie zu gießen!", "en": "Drag the water drop onto the plant to water it!", "es": "¡Arrastra la gota de agua a la planta para regarla!", "fr": "Fais glisser la goutte d'eau sur la plante pour l'arroser !", "it": "Drag the water drop onto the plant to water it!", "pt": "Arrasta a gota de água para a planta para a regares!", "ja": "水ドロップを植物の上にドラッグして水やりをしましょう！", "ko": "물방울을 식물 위로 드래그하여 물을 주세요!", "pl": "Przeciągnij kroplę wody na roślinę, aby ją podlać!", "nl": "Sleep de waterdruppel naar de plant om hem water te geven!", "tr": "Sulamak için su damlasını bitkinin üzerine sürükleyin!"],
        "onboarding_tutorial_giessen_erfolg": ["de": "Klasse! So pflegst du deine Gewohnheiten.", "en": "Great! This is how you nurture your habits.", "es": "¡Genial! Así es como cuidas tus hábitos.", "fr": "Génial ! C'est ainsi que tu cultives tes habitudes.", "it": "Great! This is how you nurture your habits.", "pt": "Espetacular! É assim que nutres os teus hábitos.", "ja": "素晴らしい！こうやって習慣を育んでいきます。", "ko": "엄청난! 이것이 습관을 키우는 방법입니다.", "pl": "Świetnie! W ten sposób pielęgnujesz swoje nawyki.", "nl": "Geweldig! Zo onderhoud je je gewoontes.", "tr": "Harika! Alışkanlıklarınızı bu şekilde beslersiniz."],
        "onboarding_tutorial_giessen_test": ["de": "Deine erste Pflanze", "en": "Your first plant", "es": "Tu primera planta", "fr": "Ta première plante", "it": "Your first plant", "pt": "A tua primeira planta", "ja": "初めての植物", "ko": "당신의 첫 번째 식물", "pl": "Twoja pierwsza roślina", "nl": "Je eerste plantje", "tr": "İlk bitkiniz"],
        "onboarding_tutorial_interactive_shop_bubble": ["de": "Im Shop kannst du deine Coins gegen tolle Gegenstände eintauschen!", "en": "In the shop, you can exchange your coins for great items!", "es": "¡En la tienda puedes canjear tus monedas por objetos geniales!", "fr": "Dans la boutique, tu peux échanger tes pièces contre de superbes objets !", "it": "In the shop, you can exchange your coins for great items!", "pt": "Na loja, podes trocar as tuas moedas por itens incríveis!", "ja": "ショップではコインを素敵なアイテムと交換できます！", "ko": "상점에서는 코인을 멋진 아이템으로 교환할 수 있어요!", "pl": "W sklepie możesz wymienić swoje monety na wspaniałe przedmioty!", "nl": "In de winkel kun je je munten inwisselen voor leuke items!", "tr": "Mağazada paralarınızı harika eşyalarla değiştirebilirsiniz!"],
        "onboarding_tutorial_interactive_shop_buy": ["de": "Kauf dir mal diesen Dünger!", "en": "Go ahead and buy this fertilizer!", "es": "¡Cómprate este fertilizante!", "fr": "Achète cet engrais !", "it": "Go ahead and buy this fertilizer!", "pt": "Compra este fertilizante!", "ja": "さあ、この肥料を購入してください！", "ko": "가서 이 비료를 사세요!", "pl": "Śmiało, kup ten nawóz!", "nl": "Ga je gang en koop deze meststof!", "tr": "Devam edin ve bu gübreyi satın alın!"],
        "onboarding_tutorial_interactive_shop_success": ["de": "Stark! Items geben dir sofortige Vorteile im Garten.", "en": "Awesome! Items give you immediate benefits in the garden.", "es": "¡Genial! Los objetos te dan beneficios inmediatos en el jardín.", "fr": "Génial ! Les objets te procurent des avantages immédiats dans le jardin.", "it": "Awesome! Items give you immediate benefits in the garden.", "pt": "Incrível! Os itens dão-te benefícios imediatos no jardim.", "ja": "素晴らしい！アイテムは庭ですぐに利益をもたらします。", "ko": "엄청난! 아이템은 정원에서 즉각적인 혜택을 제공합니다.", "pl": "Wspaniały! Przedmioty dają natychmiastowe korzyści w ogrodzie.", "nl": "Geweldig! Artikelen geven je direct voordeel in de tuin.", "tr": "Mükemmel! Öğeler bahçede size anında fayda sağlar."],
        "onboarding_tutorial_powerup_bubble": ["de": "Ich gebe dir verschiedene Effekte für den Garten. Benutze sie um schöne Fortschritte zu erreichen.", "en": "I'll give you various effects for the garden. Use them to make beautiful progress.", "es": "Te daré varios efectos para el jardín. Úsalos para lograr un progreso hermoso.", "fr": "Je vais te donner divers effets pour le jardin. Utilise-les pour faire de beaux progrès.", "it": "Ti darò vari effetti per il giardino. Usali per fare bei progressi.", "pt": "Vou dar-te vários efeitos para o jardim. Usa-os para fazeres belos progressos.", "ja": "お庭にさまざまな効果を与えます。それらを使用して、美しい進歩を遂げましょう。", "ko": "정원에 다양한 효과를 드려요. 이를 사용하여 아름다운 발전을 이루세요.", "pl": "Podam Ci różne efekty do ogrodu. Używaj ich, aby robić piękne postępy.", "nl": "Ik geef je verschillende effecten voor de tuin. Gebruik ze om mooie vooruitgang te boeken.", "tr": "Bahçe için sana çeşitli efektler vereceğim. Güzel bir ilerleme kaydetmek için bunları kullanın."],
        "onboarding_tutorial_powerup_detail_hint": ["de": "Tippe auf den Schlüssel, um ihn einzusetzen!", "en": "Tap the key to use it!", "es": "¡Toca la llave para usarla!", "fr": "Appuie sur la clé pour l'utiliser !", "it": "Tocca la chiave per usarla!", "pt": "Tocca na chave para a usares!", "ja": "キーをタップして使用してください!", "ko": "키를 탭하여 사용하세요!", "pl": "Naciśnij klawisz, aby z niego skorzystać!", "nl": "Tik op de sleutel om deze te gebruiken!", "tr": "Kullanmak için tuşa dokunun!"],
        "onboarding_tutorial_powerup_active_success": ["de": "Stark! Der Goldene Schlüssel ist nun aktiv. Du erhältst jetzt 1.5x mehr XP!", "en": "Awesome! The Golden Key is now active. You now get 1.5x more XP!", "es": "¡Genial! La Llave Dorada está activa. ¡Ahora obtienes 1.5x más XP!", "fr": "Super ! La Clé Dorée est maintenant active. Tu reçois maintenant 1.5x plus d'XP !", "it": "Ottimo! La Chiave Dorata è ora attiva. Ricevi ora 1.5x più XP!", "pt": "Incrível! A Chave Dourada está agora ativa. Recebes agora 1.5x mais XP!", "ja": "素晴らしい！ゴールデンキーがアクティブになりました。今なら 1.5 倍の XP を獲得できます!", "ko": "엄청난! 이제 황금 열쇠가 활성화되었습니다. 이제 XP가 1.5배 더 늘어납니다!", "pl": "Wspaniały! Złoty Klucz jest teraz aktywny. Otrzymasz teraz 1,5x więcej PD!", "nl": "Geweldig! De Gouden Sleutel is nu actief. Je krijgt nu 1,5x meer XP!", "tr": "Mükemmel! Altın Anahtar artık aktif. Artık 1,5 kat daha fazla XP elde edeceksiniz!"],
        "onboarding_tutorial_interactive_weed_bubble": ["de": "Unkraut macht deinen Garten schwächer und du verdienst weniger XP! Vermeide es, indem du nicht zu viele Dekorationen kaufst.", "en": "Weeds make your garden weaker and you earn less XP! Avoid them by not buying too many decorations.", "es": "¡Las malas hierbas debilitan tu jardín y ganas menos XP! Evítalas no comprando demasiadas decoraciones.", "fr": "Les mauvaises herbes affaiblissent ton jardin et tu gagnes moins d'XP ! Évite-les en n'achetant pas trop de décorations.", "it": "Le erbacce indeboliscono il tuo giardino e guadagni meno XP! Evitale non comprando troppe decorazioni.", "pt": "As ervas daninhas enfraquecem o teu jardim e ganhas menos XP! Evita-as não comprando demasiadas decorações.", "ja": "雑草が生えると庭が弱くなり、獲得できる XP も減ります。装飾品を買いすぎないように注意してください。", "ko": "잡초는 정원을 약화시키고 XP를 적게 얻습니다! 장식을 너무 많이 구입하지 않음으로써 이러한 현상을 피하세요.", "pl": "Chwasty osłabiają Twój ogród i zarabiasz mniej XP! Unikaj ich, nie kupując zbyt wielu dekoracji.", "nl": "Onkruid maakt je tuin zwakker en je verdient minder XP! Vermijd ze door niet te veel decoraties te kopen.", "tr": "Yabani otlar bahçenizi zayıflatır ve daha az XP kazanırsınız! Çok fazla dekorasyon satın almayarak bunlardan kaçının."],
        "onboarding_tutorial_interactive_weed_warning": ["de": "Dekorationen locken langfristig Unkraut an. Je mehr Deko, desto höher die Gefahr im Glücksrad!", "en": "Decorations attract weeds in the long run. The more deco, the higher the danger in the wheel!", "es": "Las decoraciones atraen malas hierbas a largo plazo. ¡A más decoración, mayor peligro en la ruleta!", "fr": "Les décorations attirent les mauvaises herbes à long terme. Plus il y a de déco, plus le danger est grand dans la roue !", "it": "Le decorazioni attraggono le erbacce a lungo termine. Più decorazioni ci sono, maggiore è il pericolo nella ruota!", "pt": "As decorações atraem ervas daninhas a longo prazo. Quanto mais decoração, maior o perigo na roleta!", "ja": "装飾は長期的には雑草を引き寄せます。デコが多ければ多いほど、ホイールの危険性が高くなります。", "ko": "장식은 장기적으로 잡초를 유인합니다. 데코가 많을수록 휠의 위험이 높아집니다!", "pl": "Dekoracje na dłuższą metę przyciągają chwasty. Im więcej deco, tym większe niebezpieczeństwo w kole!", "nl": "Decoraties trekken op den duur onkruid aan. Hoe meer decoratie, hoe groter het gevaar in het rad!", "tr": "Dekorasyonlar uzun vadede yabani otları çeker. Deko ne kadar fazla olursa, tekerlekteki tehlike de o kadar yüksek olur!"],
        "onboarding_tutorial_interactive_xp_bubble": ["de": "Tippe auf die Pflanze oben, um sie zu gießen und XP zu sammeln!", "en": "Tap the plant above to water it and collect XP!", "es": "¡Toca la planta arriba para regarla y ganar XP!", "fr": "Appuie sur la plante ci-dessus pour l'arroser et gagner de l'XP !", "it": "Tap the plant above to water it and collect XP!", "pt": "Toca na planta acima para a regares e ganhares XP!", "ja": "上の植物をタップして水をやり、XP を集めましょう!", "ko": "위의 식물을 탭하여 물을 주고 XP를 모아보세요!", "pl": "Kliknij roślinę powyżej, aby ją podlać i zebrać XP!", "nl": "Tik op de plant hierboven om hem water te geven en XP te verzamelen!", "tr": "Sulamak ve XP toplamak için yukarıdaki bitkiye dokunun!"],
        "onboarding_tutorial_interactive_xp_success": ["de": "Super! Wenn der Ring voll ist, steigt deine Pflanze ein Level auf.", "en": "Great! When the ring is full, your plant levels up.", "es": "¡Genial! Quando el círculo esté lleno, tu planta subirá de nivel.", "fr": "Super ! Quand l'anneau est plein, ta plante monte de niveau.", "it": "Great! When the ring is full, your plant levels up.", "pt": "Espetacular! Quando o anel estiver cheio, a tua planta sobe de nível.", "ja": "素晴らしい！リングがいっぱいになると、植物のレベルが上がります。", "ko": "엄청난! 링이 가득 차면 식물의 레벨이 올라갑니다.", "pl": "Świetnie! Kiedy pierścień jest pełny, twoja roślina awansuje.", "nl": "Geweldig! Als de ring vol is, gaat je plant in level omhoog.", "tr": "Harika! Halka dolduğunda bitkinizin seviyesi yükselir."],
        "onboarding_tutorial_xp_goal": ["de": "DEIN ZIEL", "en": "YOUR GOAL", "es": "TU OBJETIVO", "fr": "TON OBJECTIF", "it": "IL TUO OBIETTIVO", "pt": "O TEU OBJETIVO", "ja": "あなたの目標", "ko": "당신의 목표", "pl": "TWÓJ CEL", "nl": "UW DOEL", "tr": "HEDEFİNİZ"],
        "onboarding_tutorial_xp_success_final": ["de": "You go!", "en": "You go!", "es": "¡Tú puedes!", "fr": "C'est parti !", "it": "You go!", "pt": "Tu consegues!", "ja": "あなたが行く！", "ko": "당신은 간다!", "pl": "Idź!", "nl": "Jij gaat!", "tr": "Git!"],
        "onboarding_tutorial_weed_decoration_hint": ["de": "Kauf dir eine Deko für schnelle Boni!", "en": "Buy a decoration for quick bonuses!", "es": "¡Compra una decoración para obtener bonos rápidos!", "fr": "Achète une décoration pour des bonus rapides !", "it": "Compra una decorazione per dei bonus rapidi!", "pt": "Compra uma decoração para bónus rápidos!", "ja": "デコレーションを購入してすぐにボーナスを獲得しましょう!", "ko": "빠른 보너스를 위해 장식을 구입하세요!", "pl": "Kup dekorację, aby otrzymać szybkie bonusy!", "nl": "Koop een decoratie voor snelle bonussen!", "tr": "Hızlı bonuslar için bir dekorasyon satın alın!"],
        "onboarding_weiter": ["de": "WEITER", "en": "CONTINUE", "es": "CONTINUAR", "fr": "CONTINUER", "it": "CONTINUA", "pt": "CONTINUAR", "ja": "続く", "ko": "계속하다", "pl": "KONTYNUOWAĆ", "nl": "DOORGAAN", "tr": "DEVAM ETMEK"],
        "onboarding_willkommen_blase": ["de": "Hallo! Ich bin dein Garten-Guide. Lass uns zusammen deinen persönlichen Garten anlegen!", "en": "Hello! I'm your garden guide. Let's create your personal garden together!", "es": "¡Hola! Soy tu guía del jardín. ¡Curemos juntos tu jardín personal!", "fr": "Bonjour ! Je suis ton guide du jardin. Créons ton jardin personnel ensemble !", "it": "Hello! I'm your garden guide. Let's create your personal garden together!", "pt": "Olá! Sou o teu guia do jardim. Vamos criar o teu jardim pessoal juntos!", "ja": "こんにちは！私はあなたの庭園ガイドです。あなただけのお庭を一緒に作りましょう！", "ko": "안녕하세요! 나는 당신의 정원 가이드입니다. 나만의 정원을 함께 만들어 보세요!", "pl": "Cześć! Jestem twoim przewodnikiem po ogrodzie. Stwórzmy razem Twój osobisty ogród!", "nl": "Hallo! Ik ben jouw tuingids. Laten we samen uw persoonlijke tuin creëren!", "tr": "Merhaba! Ben senin bahçe rehberinim. Gelin kişisel bahçenizi birlikte yaratalım!"],
        "onboarding_willkommen_titel": ["de": "Willkommen im Garten", "en": "Welcome to the Garden", "es": "Bienvenido al Jardín", "fr": "Bienvenue dans le jardin", "it": "Welcome to the Garden", "pt": "Bem-vindo ao Jardim", "ja": "庭園へようこそ", "ko": "정원에 오신 것을 환영합니다", "pl": "Witamy w Ogrodzie", "nl": "Welkom in de tuin", "tr": "Bahçeye hoş geldiniz"],
        "onboarding_willkommen_untertitel": ["de": "Baue Gewohnheiten auf, die wachsen.", "en": "Build habits that grow.", "es": "Crea hábitos que crezcan.", "fr": "Crée des habitudes qui grandissent.", "it": "Build habits that grow.", "pt": "Cria hábitos que cresçam.", "ja": "成長する習慣を築きましょう。", "ko": "성장하는 습관을 길러보세요.", "pl": "Buduj nawyki, które rosną.", "nl": "Ontwikkel gewoonten die groeien.", "tr": "Büyüyen alışkanlıklar oluşturun."],
