        "settings.import.action": ["de": "Import starten", "en": "Start Import", "es": "Iniciar Importación", "fr": "Démarrer l'import", "it": "Start Import", "pt": "Iniciar importação", "ja": "インポートの開始", "ko": "가져오기 시작", "pl": "Rozpocznij import", "nl": "Start importeren", "tr": "İçe aktarmayı başlat"],
        "settings.import.desc": ["de": "Möchten Sie Daten importieren? Dies überschreibt Ihre aktuellen Fortschritte.", "en": "Do you want to import data? This will overwrite your current progress.", "es": "¿Quieres importar datos? Esto sobreescribirá tu progreso actual.", "fr": "Veux-tu importer des données ? Cela écrasera ta progression actuelle.", "it": "Do you want to import data? This will overwrite your current progress.", "pt": "Queres importar dados? Isto irá substituir o teu progresso atual.", "ja": "データをインポートしますか?これにより、現在の進行状況が上書きされます。", "ko": "데이터를 가져오시겠습니까? 현재 진행 상황을 덮어쓰게 됩니다.", "pl": "Czy chcesz zaimportować dane? Spowoduje to zastąpienie Twojego bieżącego postępu.", "nl": "Wilt u gegevens importeren? Hiermee wordt uw huidige voortgang overschreven.", "tr": "Verileri içe aktarmak istiyor musunuz? Bu, mevcut ilerlemenizin üzerine yazacaktır."],
