        "settings.restore.action": ["de": "Wiederherstellen", "en": "Restore", "es": "Restaurar", "fr": "Restaurer", "it": "Restore", "pt": "Restaurar", "ja": "復元する", "ko": "복원하다", "pl": "Przywrócić", "nl": "Herstellen", "tr": "Eski haline getirmek"],
        "settings.restore.desc": ["de": "Haben Sie bereits Käufe getätigt? Hier können Sie diese auf diesem Gerät wiederherstellen.", "en": "Have you already made purchases? You can restore them on this device here.", "es": "¿Ya realizaste compras? Puedes restaurarlas en este dispositivo aquí.", "fr": "As-tu déjà effectué des achats ? Tu peux les restaurer sur cet appareil ici.", "it": "Have you already made purchases? You can restore them on this device here.", "pt": "Já efetuaste compras? Podes restaurá-las neste dispositivo aqui.", "ja": "もう購入しましたか?ここでこのデバイスにそれらを復元できます。", "ko": "이미 구매하셨나요? 여기에서 이 기기에 복원할 수 있습니다.", "pl": "Czy dokonaliście już zakupów? Tutaj możesz je przywrócić na tym urządzeniu.", "nl": "Heeft u al aankopen gedaan? Je kunt ze hier op dit apparaat herstellen.", "tr": "Zaten alışveriş yaptınız mı? Bunları bu cihaza buradan geri yükleyebilirsiniz."],
