        "stats.empty.desc": ["de": "Pflanze und gieße deine Pflanzen, um Statistiken zu sehen.", "en": "Plant and water your plants to see statistics.", "es": "Planta y riega tus plantas para ver estadísticas.", "fr": "Plante et arrose tes plantes pour voir des statistiques.", "it": "Pianta e annaffia le tue piante per vedere le statistiche.", "pt": "Plante e regue as suas plantas para ver estatísticas.", "ja": "植物に植えて水をやり、統計を確認します。", "ko": "통계를 보려면 식물을 심고 물을 주세요.", "pl": "Sadź i podlewaj swoje rośliny, aby zobaczyć statystyki.", "nl": "Plant en geef uw planten water om statistieken te bekijken.", "tr": "İstatistikleri görmek için bitkilerinizi ekin ve sulayın."],
        
        "stats.score.msg.low": ["de": "Mach weiter so! Dein Garten wird bald wachsen.", "en": "Keep it up! Your garden will grow soon.", "es": "¡Sigue así! Tu jardín crecerá pronto.", "fr": "Continue comme ça ! Ton jardin va bientôt pousser.", "it": "Continua così! Il tuo giardino crescerà presto.", "pt": "Continua assim! O teu jardim crescerá em breve.", "ja": "それを維持する！あなたの庭はすぐに成長します。", "ko": "계속하세요! 당신의 정원은 곧 자랄 것입니다.", "pl": "Tak trzymaj! Twój ogród wkrótce się rozrośnie.", "nl": "Ga zo door! Uw tuin zal snel groeien.", "tr": "Aynen böyle devam! Bahçeniz yakında büyüyecek."],
        "stats.score.msg.excellent": ["de": "Hervorragende Arbeit! Dein Garten blüht in voller Pracht.", "en": "Excellent job! Your garden is blooming in full glory.", "es": "¡Excelente trabajo! Tu jardín está floreciendo en todo su esplendor.", "fr": "Excellent travail ! Ton jardin fleurit de mille feux.", "it": "Ottimo lavoro! Il tuo giardino sta fiorendo in tutto il suo splendore.", "pt": "Excelente trabalho! O teu jardim está a florescer em todo o seu esplendor.", "ja": "素晴らしい仕事です！あなたの庭は咲き誇ります。", "ko": "훌륭해요! 당신의 정원이 활짝 피어나고 있습니다.", "pl": "Doskonała robota! Twój ogród rozkwita w pełnej krasie.", "nl": "Uitstekend werk! Uw tuin bloeit in volle glorie.", "tr": "Mükemmel iş! Bahçeniz tüm görkemiyle çiçek açıyor."],
        "stats.score.msg.good": ["de": "Gute Arbeit! Dein Garten entwickelt sich großartig.", "en": "Good job! Your garden is developing great.", "es": "¡Buen trabalho! Tu jardín se está desarrollando genial.", "fr": "Beau travail ! Ton jardin se développe très bien.", "it": "Buon lavoro! Il tuo giardino si sta sviluppando alla grande.", "pt": "Bom trabalho! O teu jardim está a desenvolver-se muito bem.", "ja": "よくやった！あなたの庭は素晴らしい発展を遂げています。", "ko": "잘했어요! 당신의 정원은 훌륭하게 발전하고 있습니다.", "pl": "Dobra robota! Twój ogród świetnie się rozwija.", "nl": "Goed gedaan! Je tuin ontwikkelt zich geweldig.", "tr": "Aferin! Bahçeniz harika gelişiyor."],
        "stats.score.msg.ok": ["de": "Guter Anfang! Mach weiter so, um mehr zu erreichen.", "en": "Good start! Keep going to achieve more.", "es": "¡Buen comienzo! Sigue así para lograr más.", "fr": "Bon début ! Continue comme ça pour en faire plus.", "it": "Buon inizio! Continua così per ottenere di più.", "pt": "Bom começo! Continua assim para alcançar mais.", "ja": "良いスタートです！さらに多くのことを達成し続けてください。", "ko": "좋은 시작입니다! 더 많은 것을 성취하기 위해 계속 노력하세요.", "pl": "Dobry początek! Kontynuuj, aby osiągnąć więcej.", "nl": "Goed begin! Blijf doorgaan om meer te bereiken.", "tr": "İyi başlangıç! Daha fazlasını başarmak için yola devam edin."],
        
