        "stats.coach.title": ["de": "Garten-Coach", "en": "Garden Coach", "es": "Entrenador de jardín", "fr": "Coach du jardin", "it": "Coach del giardino", "pt": "Treinador de jardim", "ja": "ガーデンコーチ", "ko": "정원 코치", "pl": "Trener Ogrodniczy", "nl": "Tuincoach", "tr": "Bahçe Koçu"],
        "stats.coach.bullet1": ["de": "Gleichgewicht: Versuche, alle Lebensbereiche gleichmäßig zu pflegen.", "en": "Balance: Try to nurture all life areas equally.", "es": "Equilibrio: Intenta cultivar todas las áreas de la vida por igual.", "fr": "Équilibre : Essaie de cultiver tous les aspects de ta vie de manière égale.", "it": "Equilibrio: Cerca di coltivare tutte le aree della vita in modo uniforme.", "pt": "Equilíbrio: Tenta cultivar todas as áreas da vida igualmente.", "ja": "バランス：すべての生活領域を平等に育むように努めてください。", "ko": "균형: 모든 삶의 영역을 동등하게 육성하려고 노력하십시오.", "pl": "Równowaga: Staraj się jednakowo pielęgnować wszystkie obszary życia.", "nl": "Balans: Probeer alle levensgebieden in gelijke mate te koesteren.", "tr": "Denge: Yaşamın tüm alanlarını eşit şekilde beslemeye çalışın."],
        "stats.coach.bullet2": ["de": "Kontinuität: Tägliche kleine Schritte führen zu großem Erfolg.", "en": "Consistency: Daily small steps lead to great success.", "es": "Consistencia: Los pequeños pasos diarios llevan a un gran éxito.", "fr": "Régularité : De petits pas quotidiens mènent à un grand succès.", "it": "Costanza: Piccoli passi quotidiani portano a un grande successo.", "pt": "Consistência: Pequenos passos diários levam a um grande sucesso.", "ja": "一貫性: 毎日の小さな一歩が大きな成功につながります。", "ko": "일관성: 매일의 작은 발걸음이 큰 성공을 가져옵니다.", "pl": "Konsekwencja: codzienne małe kroki prowadzą do wielkiego sukcesu.", "nl": "Consistentie: Dagelijkse kleine stapjes leiden tot groot succes.", "tr": "Tutarlılık: Günlük küçük adımlar büyük başarıya yol açar."],
        "stats.coach.bullet3": ["de": "Achtsamkeit: Höre auf deine Bedürfnisse und passe deine Ziele an.", "en": "Mindfulness: Listen to your needs and adjust your goals.", "es": "Atención plena: Escucha tus necesidades y ajusta tus metas.", "fr": "Pleine conscience : Écoute tes besoins et ajuste tes objectifs.", "it": "Consapevolezza: Ascolta i tuoi bisogni e adatta i tuoi obiettivi.", "pt": "Mente alerta: Ouve as tuas necessidades e ajusta os teus objetivos.", "ja": "マインドフルネス: 自分のニーズに耳を傾け、目標を調整します。", "ko": "마음챙김: 귀하의 필요 사항을 듣고 목표를 조정하십시오.", "pl": "Uważność: słuchaj swoich potrzeb i dostosowuj swoje cele.", "nl": "Mindfulness: Luister naar uw behoeften en pas uw doelen aan.", "tr": "Farkındalık: İhtiyaçlarınızı dinleyin ve hedeflerinizi ayarlayın."],
        "stats.coach.bullet4": ["de": "Fortschritt: Feiere jeden Meilenstein, egal wie klein er ist.", "en": "Progress: Celebrate every milestone, no matter how small.", "es": "Progreso: Celebra cada hito, no importa lo pequeño que sea.", "fr": "Progrès : Célèbre chaque étape, aussi petite soit-elle.", "it": "Progresso: Festeggia ogni traguardo, non importa quanto piccolo.", "pt": "Progresso: Celebra cada marco, não importa quão pequeno seja.", "ja": "進歩: どんなに小さくても、すべてのマイルストーンを祝います。", "ko": "진행 상황: 아무리 작더라도 모든 이정표를 축하하세요.", "pl": "Postęp: świętuj każdy kamień milowy, bez względu na to, jak mały.", "nl": "Vooruitgang: Vier elke mijlpaal, hoe klein ook.", "tr": "İlerleme: Ne kadar küçük olursa olsun her dönüm noktasını kutlayın."],
        
        "stats.balance.description": ["de": "Deine Life Balance zeigt dir, wie gleichmäßig du dich um deine verschiedenen Gewohnheiten kümmerst.", "en": "Your Life Balance shows you how evenly you take care of your different habits.", "es": "Tu equilibrio muestra qué tan equitativamente cuidas tus diferentes hábitos.", "fr": "Ton équilibre montre à quel point tu prends soin de tes différentes habitudes de manière égale.", "it": "La tua Life Balance mostra quanto ti prendi cura delle tue diverse abitudini in modo uniforme.", "pt": "O teu equilíbrio mostra quão uniformemente cuidas dos teus diferentes hábitos.", "ja": "あなたのライフバランスは、さまざまな習慣をどれだけ均等に気をつけているかを示します。", "ko": "귀하의 생활 균형은 귀하가 다양한 습관을 얼마나 균등하게 관리하는지를 보여줍니다.", "pl": "Twój Life Balance pokazuje Ci, jak równomiernie dbasz o swoje różne nawyki.", "nl": "Uw Levensbalans laat u zien hoe gelijkmatig u met uw verschillende gewoonten omgaat.", "tr": "Yaşam Dengeniz, farklı alışkanlıklarınıza ne kadar eşit bir şekilde özen gösterdiğinizi gösterir."],
        
